// Archivo generado por tools/build.mjs — fuentes de los simuladores mini-Spark y mini-Airflow
window.PY_SOURCES = {"airflow/__init__.py":"\"\"\"mini-Airflow: simulador educativo de Apache Airflow (sintaxis de Airflow 3 y de Airflow 2).\"\"\"\nfrom ._core import DAG, Dataset, Asset  # noqa: F401\n\n__version__ = \"3.3.2-mini\"\n","airflow/_core.py":"\"\"\"\nmini-Airflow: simulador educativo de Apache Airflow.\n\nPermite definir DAGs con la misma sintaxis que Airflow 2.x (DAG, operadores,\nTaskFlow API, dependencias con >> y <<, XCom, ramas y trigger rules) y\n\"ejecutarlos\" en el navegador con dag.test(). No hay scheduler, workers ni\nbase de datos: es solo para aprender y practicar.\n\"\"\"\nimport datetime as _dt\nimport inspect as _inspect\n\n_DAG_REGISTRY = {}\n_CURRENT_DAG = []\n_CURRENT_GROUP = []\n\n\nclass AirflowException(Exception):\n    pass\n\n\nclass AirflowSkipException(AirflowException):\n    pass\n\n\nclass AirflowFailException(AirflowException):\n    pass\n\n\nclass TriggerRule:\n    ALL_SUCCESS = \"all_success\"\n    ALL_FAILED = \"all_failed\"\n    ALL_DONE = \"all_done\"\n    ONE_SUCCESS = \"one_success\"\n    ONE_FAILED = \"one_failed\"\n    NONE_FAILED = \"none_failed\"\n    NONE_FAILED_MIN_ONE_SUCCESS = \"none_failed_min_one_success\"\n    NONE_SKIPPED = \"none_skipped\"\n    ALWAYS = \"always\"\n\n\n# ------------------------------------------------------------------ DAG\nclass DAG:\n    def __init__(self, dag_id, description=None, schedule=None, schedule_interval=None, start_date=None,\n                 end_date=None, catchup=False, default_args=None, tags=None, max_active_runs=16,\n                 max_active_tasks=16, dagrun_timeout=None, params=None, doc_md=None, **kwargs):\n        if not isinstance(dag_id, str) or not dag_id:\n            raise AirflowException(\"dag_id debe ser un texto no vacío\")\n        self.dag_id = dag_id\n        self.description = description\n        self.schedule = schedule if schedule is not None else schedule_interval\n        self.schedule_interval = self.schedule\n        self.start_date = start_date\n        self.end_date = end_date\n        self.catchup = catchup\n        self.default_args = dict(default_args or {})\n        self.tags = list(tags or [])\n        self.max_active_runs = max_active_runs\n        self.max_active_tasks = max_active_tasks\n        self.dagrun_timeout = dagrun_timeout\n        self.params = dict(params or {})\n        self.doc_md = doc_md\n        self.task_dict = {}\n        self.extra = kwargs\n        _DAG_REGISTRY[dag_id] = self\n\n    def __enter__(self):\n        _CURRENT_DAG.append(self)\n        return self\n\n    def __exit__(self, *a):\n        _CURRENT_DAG.pop()\n\n    def __repr__(self):\n        return \"<DAG: %s>\" % self.dag_id\n\n    @property\n    def tasks(self):\n        return list(self.task_dict.values())\n\n    @property\n    def task_ids(self):\n        return list(self.task_dict.keys())\n\n    def get_task(self, task_id):\n        if task_id not in self.task_dict:\n            raise AirflowException(\"La tarea '%s' no existe en el DAG '%s'\" % (task_id, self.dag_id))\n        return self.task_dict[task_id]\n\n    def has_task(self, task_id):\n        return task_id in self.task_dict\n\n    @property\n    def roots(self):\n        return [t for t in self.tasks if not t.upstream_task_ids]\n\n    @property\n    def leaves(self):\n        return [t for t in self.tasks if not t.downstream_task_ids]\n\n    def topological_sort(self):\n        indeg = {t: len(self.task_dict[t].upstream_task_ids) for t in self.task_dict}\n        order = []\n        ready = [t for t in self.task_dict if indeg[t] == 0]\n        while ready:\n            t = ready.pop(0)\n            order.append(self.task_dict[t])\n            for d in sorted(self.task_dict[t].downstream_task_ids, key=list(self.task_dict).index):\n                indeg[d] -= 1\n                if indeg[d] == 0:\n                    ready.append(d)\n        if len(order) != len(self.task_dict):\n            raise AirflowException(\"¡El DAG '%s' tiene un ciclo! Un DAG debe ser acíclico.\" % self.dag_id)\n        return order\n\n    def check_cycle(self):\n        self.topological_sort()\n        return False\n\n    def tree(self):\n        \"\"\"Imprime las dependencias del DAG.\"\"\"\n        for t in self.topological_sort():\n            down = \", \".join(sorted(t.downstream_task_ids)) or \"-\"\n            print(\"%s -> %s\" % (t.task_id, down))\n\n    def test(self, execution_date=None, logical_date=None, run_conf=None, **kw):\n        \"\"\"Ejecuta todas las tareas en orden, como `airflow dags test`.\"\"\"\n        ld = logical_date or execution_date or self.start_date or _dt.datetime(2024, 1, 1)\n        if isinstance(ld, _dt.date) and not isinstance(ld, _dt.datetime):\n            ld = _dt.datetime(ld.year, ld.month, ld.day)\n        run = DagRun(self, ld, run_conf or {})\n        run.run()\n        return run\n\n\nclass DagRun:\n    def __init__(self, dag, logical_date, conf):\n        self.dag = dag\n        self.logical_date = logical_date\n        self.conf = conf\n        self.run_id = \"manual__%s\" % logical_date.isoformat()\n        self.xcoms = {}\n        self.asset_events = []\n        self.states = {}\n\n    def get_task_instance(self, task_id):\n        return TaskInstance(self.dag.get_task(task_id), self)\n\n    def run(self):\n        print(\"▶ Ejecutando DAG '%s' (logical_date=%s)\" % (self.dag.dag_id, self.logical_date.date()))\n        for task in self.dag.topological_sort():\n            if self.states.get(task.task_id) == \"skipped\":\n                print(\"  ⏭  %-22s skipped (rama no elegida)\" % task.task_id)\n                continue\n            ups = [self.states.get(u) for u in task.upstream_task_ids]\n            if not _trigger_ok(task.trigger_rule, ups):\n                state = \"upstream_failed\" if (\"failed\" in ups or \"upstream_failed\" in ups) else \"skipped\"\n                self.states[task.task_id] = state\n                print(\"  ⏭  %-22s %s\" % (task.task_id, state))\n                continue\n            ti = TaskInstance(task, self)\n            attempts = 1 + int(task.retries or 0)\n            for attempt in range(1, attempts + 1):\n                try:\n                    _ctx = ti.get_template_context()\n                    _CURRENT_CONTEXT.append(_ctx)\n                    try:\n                        result = task.execute(_ctx)\n                    finally:\n                        _CURRENT_CONTEXT.pop()\n                    if result is not None and task.do_xcom_push:\n                        self.xcoms[(task.task_id, \"return_value\")] = result\n                    self.states[task.task_id] = \"success\"\n                    print(\"  ✅ %-22s success%s\" % (task.task_id, \"\" if result is None else \"  (XCom: %r)\" % (result,)))\n                    for asset in getattr(task, \"outlets\", []) or []:\n                        if isinstance(asset, Asset):\n                            self.asset_events.append(asset)\n                            print(\"     📦 asset actualizado: %s\" % asset.uri)\n                    if getattr(task, \"_is_short_circuit\", False) and not result:\n                        print(\"     condición falsa: se saltean las tareas siguientes\")\n                        pend = list(task.downstream_task_ids)\n                        while pend:\n                            d = pend.pop()\n                            if self.states.get(d) != \"skipped\":\n                                self.states[d] = \"skipped\"\n                                if task.ignore_downstream_trigger_rules:\n                                    pend.extend(self.dag.get_task(d).downstream_task_ids)\n                    if getattr(task, \"_is_branch\", False):\n                        chosen = set(result) if isinstance(result, (list, tuple, set)) else {result}\n                        for d in task.downstream_task_ids:\n                            if d not in chosen:\n                                self.states[d] = \"skipped\"\n                    break\n                except AirflowSkipException:\n                    self.states[task.task_id] = \"skipped\"\n                    print(\"  ⏭  %-22s skipped\" % task.task_id)\n                    break\n                except Exception as e:  # noqa: BLE001\n                    if attempt < attempts and not isinstance(e, AirflowFailException):\n                        print(\"  🔁 %-22s falló (%s). Reintento %d/%d\" % (task.task_id, e, attempt, attempts - 1))\n                        continue\n                    self.states[task.task_id] = \"failed\"\n                    print(\"  ❌ %-22s failed: %s: %s\" % (task.task_id, type(e).__name__, e))\n                    if task.on_failure_callback:\n                        task.on_failure_callback(ti.get_template_context())\n        ok = all(v in (\"success\", \"skipped\") for v in self.states.values())\n        self.state = \"success\" if ok else \"failed\"\n        print(\"■ DAG run %s\" % self.state)\n        if self.asset_events:\n            # qué DAGs programados por assets se dispararían (los que esperan alguno de estos assets)\n            uris = {a.uri for a in self.asset_events}\n            for d in _DAG_REGISTRY.values():\n                sch = d.schedule if isinstance(d.schedule, (list, tuple)) else ([d.schedule] if isinstance(d.schedule, Asset) else [])\n                esperados = {a.uri for a in _flatten(list(sch)) if isinstance(a, Asset)}\n                if esperados & uris:\n                    faltan = esperados - uris\n                    print(\"  → %s %s\" % (d.dag_id, \"se dispararía ahora\" if not faltan else \"espera además: \" + \", \".join(sorted(faltan))))\n        return self\n\n\ndef _trigger_ok(rule, ups):\n    if not ups:\n        return True\n    s = ups\n    if rule == TriggerRule.ALL_SUCCESS:\n        return all(x == \"success\" for x in s)\n    if rule == TriggerRule.ALL_DONE or rule == TriggerRule.ALWAYS:\n        return True\n    if rule == TriggerRule.ONE_SUCCESS:\n        return any(x == \"success\" for x in s)\n    if rule == TriggerRule.ONE_FAILED:\n        return any(x in (\"failed\", \"upstream_failed\") for x in s)\n    if rule == TriggerRule.ALL_FAILED:\n        return all(x in (\"failed\", \"upstream_failed\") for x in s)\n    if rule == TriggerRule.NONE_FAILED:\n        return all(x not in (\"failed\", \"upstream_failed\") for x in s)\n    if rule == TriggerRule.NONE_FAILED_MIN_ONE_SUCCESS:\n        return all(x not in (\"failed\", \"upstream_failed\") for x in s) and any(x == \"success\" for x in s)\n    if rule == TriggerRule.NONE_SKIPPED:\n        return all(x != \"skipped\" for x in s)\n    return all(x == \"success\" for x in s)\n\n\nclass TaskInstance:\n    def __init__(self, task, run):\n        self.task = task\n        self.task_id = task.task_id\n        self.dag_run = run\n        self.try_number = 1\n\n    def xcom_push(self, key, value):\n        self.dag_run.xcoms[(self.task_id, key)] = value\n\n    def xcom_pull(self, task_ids=None, key=\"return_value\", default=None):\n        if isinstance(task_ids, (list, tuple)):\n            return [self.dag_run.xcoms.get((t, key), default) for t in task_ids]\n        if task_ids is None:\n            task_ids = self.task_id\n        return self.dag_run.xcoms.get((task_ids, key), default)\n\n    def get_template_context(self):\n        ld = self.dag_run.logical_date\n        # Intervalo de datos como en Airflow 3: con un cron (CronTriggerTimetable) inicio = fin = disparo;\n        # si el timetable declara interval=, el intervalo termina en el disparo; con timedelta, el período siguiente.\n        sch = self.task.dag.schedule if self.task.dag else None\n        if getattr(sch, \"interval\", None) is not None:\n            di_start, di_end = ld - sch.interval, ld\n        elif isinstance(sch, _dt.timedelta):\n            di_start, di_end = ld, ld + sch\n        else:\n            di_start, di_end = ld, ld\n        return {\n            \"ti\": self, \"task_instance\": self, \"task\": self.task, \"dag\": self.task.dag,\n            \"ds\": ld.strftime(\"%Y-%m-%d\"), \"ds_nodash\": ld.strftime(\"%Y%m%d\"),\n            \"ts\": ld.isoformat(), \"logical_date\": ld, \"execution_date\": ld,\n            \"data_interval_start\": di_start, \"data_interval_end\": di_end,\n            \"params\": dict(self.task.dag.params if self.task.dag else {}, **(self.task.params or {})),\n            \"dag_run\": self.dag_run, \"run_id\": self.dag_run.run_id, \"conf\": self.dag_run.conf,\n            \"var\": {\"value\": _VarAccessor()},\n            \"macros\": _Macros(),\n        }\n\n\nclass _VarAccessor:\n    def __getattr__(self, k):\n        return Variable.get(k)\n\n\nclass _Macros:\n    datetime = _dt.datetime\n    timedelta = _dt.timedelta\n\n    @staticmethod\n    def ds_add(ds, days):\n        return (_dt.date.fromisoformat(ds) + _dt.timedelta(days=days)).isoformat()\n\n    @staticmethod\n    def ds_format(ds, in_fmt, out_fmt):\n        return _dt.datetime.strptime(ds, in_fmt).strftime(out_fmt)\n\n\n# ------------------------------------------------------------ operadores\nclass BaseOperator:\n    template_fields = ()\n    ui_color = \"#fff\"\n\n    def __init__(self, task_id, dag=None, retries=None, retry_delay=None, trigger_rule=TriggerRule.ALL_SUCCESS,\n                 depends_on_past=False, owner=None, email=None, email_on_failure=False, pool=None,\n                 execution_timeout=None, sla=None, params=None, do_xcom_push=True, on_failure_callback=None,\n                 on_success_callback=None, priority_weight=1, queue=None, doc_md=None, **kwargs):\n        if not isinstance(task_id, str) or not task_id:\n            raise AirflowException(\"task_id debe ser un texto no vacío\")\n        dag = dag or (_CURRENT_DAG[-1] if _CURRENT_DAG else None)\n        if _CURRENT_GROUP:\n            task_id = _CURRENT_GROUP[-1].prefix + task_id\n        defaults = dict(dag.default_args) if dag else {}\n        self.task_id = task_id\n        self.dag = dag\n        self.retries = retries if retries is not None else defaults.get(\"retries\", 0)\n        self.retry_delay = retry_delay if retry_delay is not None else defaults.get(\"retry_delay\")\n        self.trigger_rule = trigger_rule\n        self.depends_on_past = depends_on_past or defaults.get(\"depends_on_past\", False)\n        self.owner = owner or defaults.get(\"owner\", \"airflow\")\n        self.email = email or defaults.get(\"email\")\n        self.pool = pool\n        # como en Airflow: lo que no se pasa a la tarea se toma de default_args del DAG\n        self.execution_timeout = execution_timeout if execution_timeout is not None else defaults.get(\"execution_timeout\")\n        self.params = params or {}\n        self.do_xcom_push = do_xcom_push\n        # Assets que esta tarea produce (outlets) o lee (inlets): base de la programación por datos\n        self.outlets = list(kwargs.get('outlets') or [])\n        self.inlets = list(kwargs.get('inlets') or [])\n        self.on_failure_callback = on_failure_callback or defaults.get(\"on_failure_callback\")\n        self.on_success_callback = on_success_callback\n        self.doc_md = doc_md\n        self.extra = kwargs\n        self.upstream_task_ids = set()\n        self.downstream_task_ids = set()\n        if dag is not None:\n            if task_id in dag.task_dict:\n                raise AirflowException(\"Ya existe una tarea con task_id '%s' en el DAG '%s' (los task_id deben ser únicos)\" % (task_id, dag.dag_id))\n            dag.task_dict[task_id] = self\n        if _CURRENT_GROUP:\n            _CURRENT_GROUP[-1].children.append(self)\n\n    def __repr__(self):\n        return \"<Task(%s): %s>\" % (type(self).__name__, self.task_id)\n\n    # ---- dependencias\n    def set_downstream(self, other):\n        for o in _flatten(other):\n            for t in _tasks_of(o):\n                self.downstream_task_ids.add(t.task_id)\n                t.upstream_task_ids.add(self.task_id)\n\n    def set_upstream(self, other):\n        for o in _flatten(other):\n            for t in _tasks_of(o):\n                t.set_downstream(self)\n\n    def __rshift__(self, other):\n        self.set_downstream(other)\n        return other\n\n    def __lshift__(self, other):\n        self.set_upstream(other)\n        return other\n\n    def __rrshift__(self, other):\n        for o in _flatten(other):\n            for t in _tasks_of(o):\n                t.set_downstream(self)\n        return self\n\n    def __rlshift__(self, other):\n        self.set_downstream(other)\n        return self\n\n    @property\n    def upstream_list(self):\n        return [self.dag.task_dict[t] for t in sorted(self.upstream_task_ids)]\n\n    @property\n    def downstream_list(self):\n        return [self.dag.task_dict[t] for t in sorted(self.downstream_task_ids)]\n\n    def render(self, value, context):\n        if isinstance(value, str) and \"{{\" in value:\n            try:\n                import jinja2\n                return jinja2.Template(value).render(**context)\n            except ImportError:\n                return value.replace(\"{{ ds }}\", context[\"ds\"]).replace(\"{{ds}}\", context[\"ds\"])\n        return value\n\n    def execute(self, context):\n        raise NotImplementedError\n\n\ndef _output(self):\n    \"\"\"op.output: el XCom return_value de un operador clásico, para pasarlo a una tarea @task.\"\"\"\n    return XComArg(self)\n\n\nBaseOperator.output = property(_output)\n\n\ndef _flatten(x):\n    if isinstance(x, (list, tuple, set)):\n        out = []\n        for y in x:\n            out.extend(_flatten(y))\n        return out\n    return [x]\n\n\ndef _tasks_of(x):\n    if isinstance(x, TaskGroup):\n        return x.roots()\n    if isinstance(x, XComArg):\n        return [x.operator]\n    return [x]\n\n\nclass EmptyOperator(BaseOperator):\n    def execute(self, context):\n        return None\n\n\nDummyOperator = EmptyOperator\n\n\nclass BashOperator(BaseOperator):\n    template_fields = (\"bash_command\", \"env\")\n\n    def __init__(self, task_id, bash_command, env=None, cwd=None, **kw):\n        super().__init__(task_id, **kw)\n        self.bash_command = bash_command\n        self.env = env\n        self.cwd = cwd\n\n    def execute(self, context):\n        cmd = self.render(self.bash_command, context)\n        print(\"     $ %s\" % cmd)\n        if \"exit 1\" in cmd or \"false\" == cmd.strip():\n            raise AirflowException(\"El comando bash terminó con código 1\")\n        last = cmd.strip().split(\"\\n\")[-1]\n        if last.startswith(\"echo \"):\n            out = last[5:].strip().strip(\"'\\\"\")\n            print(\"     %s\" % out)\n            return out\n        return None\n\n\nclass PythonOperator(BaseOperator):\n    template_fields = (\"op_args\", \"op_kwargs\")\n\n    def __init__(self, task_id, python_callable, op_args=None, op_kwargs=None, templates_dict=None, **kw):\n        super().__init__(task_id, **kw)\n        if not callable(python_callable):\n            raise AirflowException(\"python_callable debe ser una función\")\n        self.python_callable = python_callable\n        self.op_args = list(op_args or [])\n        self.op_kwargs = dict(op_kwargs or {})\n        self.templates_dict = templates_dict\n\n    def execute(self, context):\n        args = [self.render(a, context) for a in self.op_args]\n        kwargs = {k: self.render(v, context) for k, v in self.op_kwargs.items()}\n        if self.templates_dict:\n            context[\"templates_dict\"] = {k: self.render(v, context) for k, v in self.templates_dict.items()}\n        return _call_with_context(self.python_callable, args, kwargs, context)\n\n\ndef _call_with_context(fn, args, kwargs, context):\n    sig = _inspect.signature(fn)\n    params = sig.parameters\n    accepts_var_kw = any(p.kind == p.VAR_KEYWORD for p in params.values())\n    for k, v in context.items():\n        if accepts_var_kw or (k in params and k not in kwargs):\n            if k not in kwargs and (accepts_var_kw or k in params):\n                # no pisar argumentos posicionales\n                names = list(params)\n                if k in names and names.index(k) < len(args):\n                    continue\n                kwargs[k] = v\n    return fn(*args, **kwargs)\n\n\nclass BranchPythonOperator(PythonOperator):\n    _is_branch = True\n\n\nclass ShortCircuitOperator(PythonOperator):\n    \"\"\"Como en Airflow: la tarea termina en success y, si la condición es falsa, se saltean todas las siguientes.\"\"\"\n    _is_short_circuit = True\n\n    def __init__(self, task_id, python_callable, ignore_downstream_trigger_rules=True, **kw):\n        super().__init__(task_id, python_callable=python_callable, **kw)\n        self.ignore_downstream_trigger_rules = ignore_downstream_trigger_rules\n\n\nclass BaseSensorOperator(BaseOperator):\n    def __init__(self, task_id, poke_interval=60, timeout=3600, mode=\"poke\", soft_fail=False, **kw):\n        super().__init__(task_id, **kw)\n        self.poke_interval = poke_interval\n        self.timeout = timeout\n        self.mode = mode\n        self.soft_fail = soft_fail\n\n    def poke(self, context):\n        return True\n\n    def execute(self, context):\n        if not self.poke(context):\n            if self.soft_fail:\n                raise AirflowSkipException(\"sensor sin éxito (soft_fail)\")\n            raise AirflowException(\"Timeout del sensor %s\" % self.task_id)\n        print(\"     sensor OK (simulado)\")\n\n\nclass FileSensor(BaseSensorOperator):\n    def __init__(self, task_id, filepath, fs_conn_id=\"fs_default\", **kw):\n        super().__init__(task_id, **kw)\n        self.filepath = filepath\n\n\nclass ExternalTaskSensor(BaseSensorOperator):\n    def __init__(self, task_id, external_dag_id, external_task_id=None, **kw):\n        super().__init__(task_id, **kw)\n        self.external_dag_id = external_dag_id\n        self.external_task_id = external_task_id\n\n\nclass PythonSensor(BaseSensorOperator):\n    def __init__(self, task_id, python_callable, op_args=None, op_kwargs=None, **kw):\n        super().__init__(task_id, **kw)\n        self.python_callable = python_callable\n        self.op_args = op_args or []\n        self.op_kwargs = op_kwargs or {}\n\n    def poke(self, context):\n        return _call_with_context(self.python_callable, list(self.op_args), dict(self.op_kwargs), context)\n\n\nclass TriggerDagRunOperator(BaseOperator):\n    def __init__(self, task_id, trigger_dag_id, conf=None, wait_for_completion=False, **kw):\n        super().__init__(task_id, **kw)\n        self.trigger_dag_id = trigger_dag_id\n        self.conf = conf\n\n    def execute(self, context):\n        print(\"     (simulado) disparando DAG '%s'\" % self.trigger_dag_id)\n\n\nclass _RecordingOperator(BaseOperator):\n    \"\"\"Operadores de proveedores: guardan su configuración y simulan la ejecución.\"\"\"\n\n    def __init__(self, task_id, **kw):\n        base_keys = set(_inspect.signature(BaseOperator.__init__).parameters)\n        own = {k: v for k, v in kw.items() if k not in base_keys}\n        base = {k: v for k, v in kw.items() if k in base_keys}\n        super().__init__(task_id, **base)\n        for k, v in own.items():\n            setattr(self, k, v)\n        self.config = own\n\n    def execute(self, context):\n        print(\"     (simulado) %s con %s\" % (type(self).__name__, \", \".join(\"%s=%r\" % kv for kv in self.config.items())))\n\n\nclass DatabricksRunNowOperator(_RecordingOperator):\n    pass\n\n\nclass DatabricksSubmitRunOperator(_RecordingOperator):\n    pass\n\n\nclass DatabricksSqlOperator(_RecordingOperator):\n    pass\n\n\nclass SQLExecuteQueryOperator(_RecordingOperator):\n    pass\n\n\nclass EmailOperator(_RecordingOperator):\n    pass\n\n\n\n# ---------------------------------------------------------------- proveedores de nube (AWS y Google Cloud)\nclass _RecordingSensor(BaseSensorOperator):\n    \"\"\"Sensores de proveedores: guardan su configuración y se cumplen al instante.\"\"\"\n\n    def __init__(self, task_id, **kw):\n        base_keys = set(_inspect.signature(BaseSensorOperator.__init__).parameters) | set(_inspect.signature(BaseOperator.__init__).parameters)\n        own = {k: v for k, v in kw.items() if k not in base_keys}\n        base = {k: v for k, v in kw.items() if k in base_keys}\n        super().__init__(task_id, **base)\n        for k, v in own.items():\n            setattr(self, k, v)\n        self.config = own\n\n    def poke(self, context):\n        print(\"     (simulado) %s: condición cumplida (%s)\" % (type(self).__name__, \", \".join(\"%s=%r\" % kv for kv in self.config.items())))\n        return True\n\n\nclass S3CreateBucketOperator(_RecordingOperator):\n    pass\n\n\nclass S3CreateObjectOperator(_RecordingOperator):\n    pass\n\n\nclass S3CopyObjectOperator(_RecordingOperator):\n    pass\n\n\nclass S3DeleteObjectsOperator(_RecordingOperator):\n    pass\n\n\nclass GlueJobOperator(_RecordingOperator):\n    pass\n\n\nclass GlueCrawlerOperator(_RecordingOperator):\n    pass\n\n\nclass AthenaOperator(_RecordingOperator):\n    pass\n\n\nclass EmrServerlessStartJobOperator(_RecordingOperator):\n    pass\n\n\nclass EmrCreateJobFlowOperator(_RecordingOperator):\n    pass\n\n\nclass EmrAddStepsOperator(_RecordingOperator):\n    pass\n\n\nclass EmrTerminateJobFlowOperator(_RecordingOperator):\n    pass\n\n\nclass RedshiftDataOperator(_RecordingOperator):\n    pass\n\n\nclass LambdaInvokeFunctionOperator(_RecordingOperator):\n    pass\n\n\nclass StepFunctionStartExecutionOperator(_RecordingOperator):\n    pass\n\n\nclass S3KeySensor(_RecordingSensor):\n    pass\n\n\nclass GlueJobSensor(_RecordingSensor):\n    pass\n\n\nclass GlueCrawlerSensor(_RecordingSensor):\n    pass\n\n\nclass AthenaSensor(_RecordingSensor):\n    pass\n\n\nclass GCSCreateBucketOperator(_RecordingOperator):\n    pass\n\n\nclass GCSDeleteObjectsOperator(_RecordingOperator):\n    pass\n\n\nclass GCSToBigQueryOperator(_RecordingOperator):\n    pass\n\n\nclass BigQueryInsertJobOperator(_RecordingOperator):\n    pass\n\n\nclass BigQueryCreateEmptyDatasetOperator(_RecordingOperator):\n    pass\n\n\nclass BigQueryCheckOperator(_RecordingOperator):\n    pass\n\n\nclass DataprocCreateClusterOperator(_RecordingOperator):\n    pass\n\n\nclass DataprocSubmitJobOperator(_RecordingOperator):\n    pass\n\n\nclass DataprocDeleteClusterOperator(_RecordingOperator):\n    pass\n\n\nclass DataprocCreateBatchOperator(_RecordingOperator):\n    pass\n\n\nclass DataflowStartFlexTemplateOperator(_RecordingOperator):\n    pass\n\n\nclass DataformCreateCompilationResultOperator(_RecordingOperator):\n    pass\n\n\nclass DataformCreateWorkflowInvocationOperator(_RecordingOperator):\n    pass\n\n\nclass GCSObjectExistenceSensor(_RecordingSensor):\n    pass\n\n\nclass BigQueryTableExistenceSensor(_RecordingSensor):\n    pass\n\n\n# ---------------------------------------------------------------- TaskGroup\nclass TaskGroup:\n    def __init__(self, group_id, tooltip=None, prefix_group_id=True, dag=None, **kw):\n        self.group_id = group_id\n        parent = _CURRENT_GROUP[-1].prefix if _CURRENT_GROUP else \"\"\n        self.prefix = (parent + group_id + \".\") if prefix_group_id else parent\n        self.children = []\n\n    def __enter__(self):\n        _CURRENT_GROUP.append(self)\n        return self\n\n    def __exit__(self, *a):\n        _CURRENT_GROUP.pop()\n\n    def _ids(self):\n        return set(t.task_id for t in self.children)\n\n    def roots(self):\n        ids = self._ids()\n        return [t for t in self.children if not (t.upstream_task_ids & ids)]\n\n    def leaves(self):\n        ids = self._ids()\n        return [t for t in self.children if not (t.downstream_task_ids & ids)]\n\n    def __rshift__(self, other):\n        for t in self.leaves():\n            t.set_downstream(other)\n        return other\n\n    def __lshift__(self, other):\n        for t in self.roots():\n            t.set_upstream(other)\n        return other\n\n    def __rrshift__(self, other):\n        for o in _flatten(other):\n            for src in (o.leaves() if isinstance(o, TaskGroup) else _tasks_of(o)):\n                for t in self.roots():\n                    src.set_downstream(t)\n        return self\n\n\n# ---------------------------------------------------------------- TaskFlow\nclass XComArg:\n    def __init__(self, operator, key=\"return_value\"):\n        self.operator = operator\n        self.key = key\n\n    def resolve(self, run):\n        return run.xcoms.get((self.operator.task_id, self.key))\n\n    def __getitem__(self, k):\n        return _XComItem(self, k)\n\n    def __rshift__(self, other):\n        self.operator.set_downstream(other)\n        return other\n\n    def __lshift__(self, other):\n        self.operator.set_upstream(other)\n        return other\n\n    def __rrshift__(self, other):\n        for o in _flatten(other):\n            for t in _tasks_of(o):\n                t.set_downstream(self.operator)\n        return self\n\n    @property\n    def task_id(self):\n        return self.operator.task_id\n\n    def __repr__(self):\n        return \"XComArg(%s)\" % self.operator.task_id\n\n\nclass _XComItem(XComArg):\n    def __init__(self, parent, k):\n        super().__init__(parent.operator, parent.key)\n        self.k = k\n\n    def resolve(self, run):\n        v = super().resolve(run)\n        return None if v is None else v[self.k]\n\n\ndef _resolve_args(obj, run):\n    if isinstance(obj, XComArg):\n        return obj.resolve(run)\n    if isinstance(obj, list):\n        return [_resolve_args(x, run) for x in obj]\n    if isinstance(obj, tuple):\n        return tuple(_resolve_args(x, run) for x in obj)\n    if isinstance(obj, dict):\n        return {k: _resolve_args(v, run) for k, v in obj.items()}\n    return obj\n\n\ndef _xcom_deps(obj):\n    if isinstance(obj, XComArg):\n        return [obj.operator]\n    if isinstance(obj, (list, tuple)):\n        return [d for x in obj for d in _xcom_deps(x)]\n    if isinstance(obj, dict):\n        return [d for x in obj.values() for d in _xcom_deps(x)]\n    return []\n\n\n_CURRENT_CONTEXT = []\n\n\ndef get_current_context():\n    \"\"\"Devuelve el contexto de la tarea que se está ejecutando (ds, logical_date, ti, params…).\"\"\"\n    if not _CURRENT_CONTEXT:\n        raise AirflowException(\"get_current_context() solo funciona dentro de una tarea en ejecución\")\n    return _CURRENT_CONTEXT[-1]\n\n\nclass _DecoratedOperator(BaseOperator):\n    def __init__(self, task_id, fn, args, kwargs, multiple_outputs=False, branch=False, **kw):\n        super().__init__(task_id, **kw)\n        self.python_callable = fn\n        self.op_args = args\n        self.op_kwargs = kwargs\n        self.multiple_outputs = multiple_outputs\n        self._is_branch = branch\n        for dep in _xcom_deps(list(args) + list(kwargs.values())):\n            dep.set_downstream(self)\n\n    def execute(self, context):\n        run = context[\"dag_run\"]\n        args = _resolve_args(list(self.op_args), run)\n        kwargs = _resolve_args(dict(self.op_kwargs), run)\n        res = _call_with_context(self.python_callable, args, kwargs, context)\n        if self.multiple_outputs and isinstance(res, dict):\n            for k, v in res.items():\n                run.xcoms[(self.task_id, k)] = v\n        return res\n\n\nclass _TaskDecorator:\n    def __init__(self, fn=None, branch=False, **opts):\n        self.fn = fn\n        self.opts = opts\n        self.branch = branch\n\n    def __call__(self, *args, **kwargs):\n        if self.fn is None:\n            # usado como @task(...) -> recibimos la función\n            return _TaskDecorator(args[0], self.branch, **self.opts)\n        dag = _CURRENT_DAG[-1] if _CURRENT_DAG else None\n        if dag is None:\n            raise AirflowException(\"Las tareas @task deben llamarse dentro de un DAG (with DAG(...) o una función @dag)\")\n        base_id = self.opts.get(\"task_id\") or self.fn.__name__\n        tid = base_id\n        prefix = _CURRENT_GROUP[-1].prefix if _CURRENT_GROUP else \"\"\n        k = 1\n        while (prefix + tid) in dag.task_dict:\n            tid = \"%s__%d\" % (base_id, k)\n            k += 1\n        opts = {kk: v for kk, v in self.opts.items() if kk != \"task_id\"}\n        op = _DecoratedOperator(tid, self.fn, args, kwargs, branch=self.branch, **opts)\n        return XComArg(op)\n\n    def partial(self, **kwargs):\n        return _PartialTask(self, kwargs)\n\n    def expand(self, **mapped):\n        return _PartialTask(self, {}).expand(**mapped)\n\n    def override(self, **opts):\n        o = dict(self.opts)\n        o.update(opts)\n        return _TaskDecorator(self.fn, self.branch, **o)\n\n    @property\n    def __name__(self):\n        return self.fn.__name__ if self.fn else \"task\"\n\n\nclass _MappedDecoratedOperator(_DecoratedOperator):\n    \"\"\"Mapeo dinámico (task.expand): una instancia de la tarea por cada valor (producto si hay varias listas).\"\"\"\n    def __init__(self, task_id, fn, fixed, mapped, **kw):\n        super().__init__(task_id, fn, [], dict(fixed, **mapped), **kw)\n        self.fixed = fixed\n        self.mapped = mapped\n\n    def execute(self, context):\n        import itertools\n        run = context[\"dag_run\"]\n        fixed = _resolve_args(dict(self.fixed), run)\n        mapped = _resolve_args(dict(self.mapped), run)\n        claves = list(mapped)\n        for k in claves:\n            if not isinstance(mapped[k], (list, tuple)):\n                raise AirflowException(\"expand(%s=...) necesita una lista (o el resultado de una tarea que devuelva una lista)\" % k)\n        resultados = []\n        combos = list(itertools.product(*[mapped[k] for k in claves]))\n        print(\"  ↳ %s: %d instancias mapeadas\" % (self.task_id, len(combos)))\n        for i, combo in enumerate(combos):\n            kw = dict(fixed)\n            kw.update(dict(zip(claves, combo)))\n            resultados.append(_call_with_context(self.python_callable, [], kw, dict(context, map_index=i)))\n        return resultados\n\n\nclass _PartialTask:\n    def __init__(self, deco, fixed):\n        self.deco = deco\n        self.fixed = fixed\n\n    def expand(self, **mapped):\n        dag = _CURRENT_DAG[-1] if _CURRENT_DAG else None\n        if dag is None:\n            raise AirflowException(\"expand() debe llamarse dentro de un DAG\")\n        base_id = self.deco.opts.get(\"task_id\") or self.deco.fn.__name__\n        tid, k = base_id, 1\n        prefix = _CURRENT_GROUP[-1].prefix if _CURRENT_GROUP else \"\"\n        while (prefix + tid) in dag.task_dict:\n            tid = \"%s__%d\" % (base_id, k)\n            k += 1\n        opts = {kk: v for kk, v in self.deco.opts.items() if kk != \"task_id\"}\n        return XComArg(_MappedDecoratedOperator(tid, self.deco.fn, self.fixed, mapped, **opts))\n\n\nclass _TaskNamespace:\n    def __call__(self, fn=None, **opts):\n        if callable(fn):\n            return _TaskDecorator(fn, **opts)\n        return _TaskDecorator(None, **opts)\n\n    def branch(self, fn=None, **opts):\n        if callable(fn):\n            return _TaskDecorator(fn, branch=True, **opts)\n        return _TaskDecorator(None, branch=True, **opts)\n\n    def python(self, fn=None, **opts):\n        return self(fn, **opts)\n\n    def bash(self, fn=None, **opts):\n        def wrap(f):\n            def make(*a, **k):\n                dag = _CURRENT_DAG[-1]\n                cmd = f(*a, **k)\n                return BashOperator(task_id=opts.get(\"task_id\", f.__name__), bash_command=cmd, dag=dag)\n            return make\n        return wrap(fn) if callable(fn) else wrap\n\n\ntask = _TaskNamespace()\n\n\ndef dag(dag_id=None, **dag_kwargs):\n    def wrap(fn):\n        def make(*args, **kwargs):\n            d = DAG(dag_kwargs.pop(\"dag_id\", None) or (dag_id if isinstance(dag_id, str) else fn.__name__), **dag_kwargs)\n            with d:\n                fn(*args, **kwargs)\n            return d\n        make.__name__ = fn.__name__\n        return make\n    if callable(dag_id):\n        fn, dag_id = dag_id, None\n        return wrap(fn)\n    return wrap\n\n\ndef task_group(group_id=None, **kw):\n    def wrap(fn):\n        def make(*a, **k):\n            with TaskGroup(group_id if isinstance(group_id, str) else fn.__name__, **kw):\n                return fn(*a, **k)\n        return make\n    if callable(group_id):\n        fn = group_id\n        group_id = None\n        return wrap(fn)\n    return wrap\n\n\ndef chain(*tasks):\n    for a, b in zip(tasks, tasks[1:]):\n        if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):\n            if len(a) != len(b):\n                raise AirflowException(\"chain: las listas consecutivas deben tener el mismo tamaño\")\n            for x, y in zip(a, b):\n                x >> y\n        else:\n            a >> b\n\n\ndef cross_downstream(from_tasks, to_tasks):\n    for a in from_tasks:\n        for b in to_tasks:\n            a >> b\n\n\n# ------------------------------------------------------------- Variables etc.\n_VARIABLES = {}\n_CONNECTIONS = {}\n\n\nclass Variable:\n    @staticmethod\n    def get(key, default_var=None, deserialize_json=False):\n        if key not in _VARIABLES:\n            if default_var is not None:\n                return default_var\n            raise KeyError(\"Variable %s no existe\" % key)\n        v = _VARIABLES[key]\n        if deserialize_json:\n            import json\n            return json.loads(v)\n        return v\n\n    @staticmethod\n    def set(key, value, serialize_json=False):\n        if serialize_json:\n            import json\n            value = json.dumps(value)\n        _VARIABLES[key] = value\n\n\nclass Connection:\n    def __init__(self, conn_id, conn_type=None, host=None, login=None, password=None, schema=None, port=None, extra=None):\n        self.conn_id = conn_id\n        self.conn_type = conn_type\n        self.host = host\n        self.login = login\n        self.password = password\n        self.schema = schema\n        self.port = port\n        self.extra = extra\n        _CONNECTIONS[conn_id] = self\n\n\nclass Asset:\n    \"\"\"Airflow 3: un dato (tabla, archivo, carpeta) que una tarea produce y otros DAGs esperan.\n    Asset(\"s3://lago/ventas\") o Asset(name=\"ventas\", uri=\"s3://lago/ventas\").\"\"\"\n    def __init__(self, name=None, uri=None, group=\"asset\", extra=None, watchers=None):\n        if name is None and uri is None:\n            raise AirflowException(\"Asset necesita name o uri\")\n        self.name = name if name is not None else uri\n        self.uri = uri if uri is not None else name\n        self.group = group\n        self.extra = dict(extra or {})\n\n    def __eq__(self, other):\n        return isinstance(other, Asset) and other.uri == self.uri\n\n    def __hash__(self):\n        return hash(self.uri)\n\n    def __or__(self, other):\n        return AssetAny(self, other)\n\n    def __and__(self, other):\n        return AssetAll(self, other)\n\n    def __repr__(self):\n        return \"Asset(name=%r, uri=%r)\" % (self.name, self.uri)\n\n\nclass AssetAll(list):\n    def __init__(self, *assets):\n        super().__init__(assets)\n\n\nclass AssetAny(list):\n    def __init__(self, *assets):\n        super().__init__(assets)\n\n\nclass Dataset(Asset):\n    \"\"\"Nombre de Airflow 2 (2.4 a 2.11); en Airflow 3 se llama Asset.\"\"\"\n    def __init__(self, uri, extra=None):\n        super().__init__(uri=uri, extra=extra)\n\n    def __repr__(self):\n        return \"Dataset(%r)\" % self.uri\n\n\ndef days_ago(n, hour=0):\n    today = _dt.datetime.now().replace(hour=hour, minute=0, second=0, microsecond=0)\n    return today - _dt.timedelta(days=n)\n\n\ndef reset():\n    _DAG_REGISTRY.clear()\n    _CURRENT_DAG.clear()\n    _CURRENT_GROUP.clear()\n    _VARIABLES.clear()\n","airflow/datasets.py":"from ._core import Dataset  # noqa: F401\n","airflow/decorators/__init__.py":"from .._core import dag, task, task_group  # noqa: F401\n","airflow/exceptions.py":"from ._core import AirflowException, AirflowSkipException, AirflowFailException  # noqa: F401\n","airflow/models/__init__.py":"from .._core import DAG, BaseOperator, Variable, Connection, TaskInstance, DagRun  # noqa: F401\nfrom .._core import XComArg  # noqa: F401\n","airflow/models/baseoperator.py":"from .._core import BaseOperator, chain, cross_downstream  # noqa: F401\n","airflow/models/dag.py":"from .._core import DAG  # noqa: F401\n","airflow/models/param.py":"class Param:\n    def __init__(self, default=None, type=None, **kw):\n        self.default = default\n        self.type = type\n        self.value = default\n","airflow/operators/__init__.py":"","airflow/operators/bash.py":"from .._core import BashOperator  # noqa: F401\n","airflow/operators/bash_operator.py":"from .._core import BashOperator  # noqa: F401\n","airflow/operators/dummy.py":"from .._core import DummyOperator  # noqa: F401\n","airflow/operators/email.py":"from .._core import EmailOperator  # noqa: F401\n","airflow/operators/empty.py":"from .._core import EmptyOperator  # noqa: F401\n","airflow/operators/python.py":"from .._core import PythonOperator, BranchPythonOperator, ShortCircuitOperator  # noqa: F401\nfrom .._core import get_current_context  # noqa: F401\n","airflow/operators/trigger_dagrun.py":"from .._core import TriggerDagRunOperator  # noqa: F401\n","airflow/providers/__init__.py":"","airflow/providers/amazon/__init__.py":"","airflow/providers/amazon/aws/__init__.py":"","airflow/providers/amazon/aws/operators/__init__.py":"","airflow/providers/amazon/aws/operators/athena.py":"from ....._core import AthenaOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/emr.py":"from ....._core import EmrServerlessStartJobOperator, EmrCreateJobFlowOperator, EmrAddStepsOperator, EmrTerminateJobFlowOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/glue.py":"from ....._core import GlueJobOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/glue_crawler.py":"from ....._core import GlueCrawlerOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/lambda_function.py":"from ....._core import LambdaInvokeFunctionOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/redshift_data.py":"from ....._core import RedshiftDataOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/s3.py":"from ....._core import S3CreateBucketOperator, S3CreateObjectOperator, S3CopyObjectOperator, S3DeleteObjectsOperator  # noqa: F401\n","airflow/providers/amazon/aws/operators/step_function.py":"from ....._core import StepFunctionStartExecutionOperator  # noqa: F401\n","airflow/providers/amazon/aws/sensors/__init__.py":"","airflow/providers/amazon/aws/sensors/athena.py":"from ....._core import AthenaSensor  # noqa: F401\n","airflow/providers/amazon/aws/sensors/glue.py":"from ....._core import GlueJobSensor  # noqa: F401\n","airflow/providers/amazon/aws/sensors/glue_crawler.py":"from ....._core import GlueCrawlerSensor  # noqa: F401\n","airflow/providers/amazon/aws/sensors/s3.py":"from ....._core import S3KeySensor  # noqa: F401\n","airflow/providers/common/__init__.py":"","airflow/providers/common/sql/__init__.py":"","airflow/providers/common/sql/operators/__init__.py":"","airflow/providers/common/sql/operators/sql.py":"from ....._core import SQLExecuteQueryOperator  # noqa: F401\n","airflow/providers/databricks/__init__.py":"","airflow/providers/databricks/operators/__init__.py":"","airflow/providers/databricks/operators/databricks.py":"from ...._core import DatabricksRunNowOperator, DatabricksSubmitRunOperator  # noqa: F401\n","airflow/providers/databricks/operators/databricks_sql.py":"from ...._core import DatabricksSqlOperator  # noqa: F401\n","airflow/providers/google/__init__.py":"","airflow/providers/google/cloud/__init__.py":"","airflow/providers/google/cloud/operators/__init__.py":"","airflow/providers/google/cloud/operators/bigquery.py":"from ....._core import BigQueryInsertJobOperator, BigQueryCreateEmptyDatasetOperator, BigQueryCheckOperator  # noqa: F401\n","airflow/providers/google/cloud/operators/dataflow.py":"from ....._core import DataflowStartFlexTemplateOperator  # noqa: F401\n","airflow/providers/google/cloud/operators/dataform.py":"from ....._core import DataformCreateCompilationResultOperator, DataformCreateWorkflowInvocationOperator  # noqa: F401\n","airflow/providers/google/cloud/operators/dataproc.py":"from ....._core import DataprocCreateClusterOperator, DataprocSubmitJobOperator, DataprocDeleteClusterOperator, DataprocCreateBatchOperator  # noqa: F401\n","airflow/providers/google/cloud/operators/gcs.py":"from ....._core import GCSCreateBucketOperator, GCSDeleteObjectsOperator  # noqa: F401\n","airflow/providers/google/cloud/sensors/__init__.py":"","airflow/providers/google/cloud/sensors/bigquery.py":"from ....._core import BigQueryTableExistenceSensor  # noqa: F401\n","airflow/providers/google/cloud/sensors/gcs.py":"from ....._core import GCSObjectExistenceSensor  # noqa: F401\n","airflow/providers/google/cloud/transfers/__init__.py":"","airflow/providers/google/cloud/transfers/gcs_to_bigquery.py":"from ....._core import GCSToBigQueryOperator  # noqa: F401\n","airflow/providers/standard/__init__.py":"","airflow/providers/standard/operators/__init__.py":"","airflow/providers/standard/operators/bash.py":"from ...._core import BashOperator  # noqa: F401\n","airflow/providers/standard/operators/empty.py":"from ...._core import EmptyOperator  # noqa: F401\n","airflow/providers/standard/operators/python.py":"from ...._core import PythonOperator, BranchPythonOperator, ShortCircuitOperator  # noqa: F401\nfrom ...._core import get_current_context  # noqa: F401\n","airflow/providers/standard/operators/trigger_dagrun.py":"from ...._core import TriggerDagRunOperator  # noqa: F401\n","airflow/providers/standard/sensors/__init__.py":"","airflow/providers/standard/sensors/external_task.py":"from ...._core import ExternalTaskSensor  # noqa: F401\n","airflow/providers/standard/sensors/filesystem.py":"from ...._core import FileSensor  # noqa: F401\n","airflow/providers/standard/sensors/python.py":"from ...._core import PythonSensor  # noqa: F401\n","airflow/providers/standard/utils/__init__.py":"","airflow/sdk/__init__.py":"\"\"\"airflow.sdk: la interfaz pública para escribir DAGs en Airflow 3 (Task SDK).\"\"\"\nfrom .._core import (  # noqa: F401\n    DAG, dag, task, task_group, TaskGroup, BaseOperator, BaseSensorOperator, Variable, Connection,\n    Asset, AssetAll, AssetAny, chain, cross_downstream, TriggerRule, get_current_context,\n)\nfrom ..models.param import Param  # noqa: F401\n\nContext = dict\n","airflow/sdk/definitions.py":"","airflow/sensors/__init__.py":"","airflow/sensors/base.py":"from .._core import BaseSensorOperator  # noqa: F401\n","airflow/sensors/external_task.py":"from .._core import ExternalTaskSensor  # noqa: F401\n","airflow/sensors/filesystem.py":"from .._core import FileSensor  # noqa: F401\n","airflow/sensors/python.py":"from .._core import PythonSensor  # noqa: F401\n","airflow/timetables/__init__.py":"","airflow/timetables/interval.py":"\"\"\"Timetables \"de intervalo de datos\" (el comportamiento por defecto de Airflow 2).\"\"\"\n\n\nclass CronDataIntervalTimetable:\n    def __init__(self, cron, timezone=\"UTC\"):\n        self.cron = cron\n        self.timezone = timezone\n\n\nclass DeltaDataIntervalTimetable:\n    def __init__(self, delta):\n        self.delta = delta\n","airflow/timetables/trigger.py":"\"\"\"Timetables de Airflow 3: CronTriggerTimetable (por defecto para cron) y MultipleCronTriggerTimetable.\"\"\"\n\n\nclass CronTriggerTimetable:\n    def __init__(self, cron, timezone=\"UTC\", interval=None, run_immediately=False):\n        self.cron = cron\n        self.timezone = timezone\n        self.interval = interval\n        self.run_immediately = run_immediately\n\n    def __repr__(self):\n        return \"CronTriggerTimetable(%r, interval=%r)\" % (self.cron, self.interval)\n\n\nclass MultipleCronTriggerTimetable:\n    def __init__(self, *crons, timezone=\"UTC\", interval=None):\n        self.crons = list(crons)\n        self.timezone = timezone\n        self.interval = interval\n\n\nclass DeltaTriggerTimetable:\n    def __init__(self, delta, interval=None):\n        self.delta = delta\n        self.interval = interval\n","airflow/utils/__init__.py":"","airflow/utils/dates.py":"from .._core import days_ago  # noqa: F401\n","airflow/utils/task_group.py":"from .._core import TaskGroup  # noqa: F401\n","airflow/utils/trigger_rule.py":"from .._core import TriggerRule  # noqa: F401\n","pendulum/__init__.py":"\"\"\"Shim mínimo de pendulum para el simulador.\"\"\"\nimport datetime as _dt\n\n\ndef datetime(year, month=1, day=1, hour=0, minute=0, second=0, tz=\"UTC\"):\n    return _dt.datetime(year, month, day, hour, minute, second, tzinfo=_dt.timezone.utc)\n\n\ndef now(tz=\"UTC\"):\n    return _dt.datetime.now(_dt.timezone.utc)\n\n\ndef duration(**kw):\n    return _dt.timedelta(**kw)\n\n\ndef today(tz=\"UTC\"):\n    return now().replace(hour=0, minute=0, second=0, microsecond=0)\n","pyspark/__init__.py":"\"\"\"mini-Spark: simulador educativo de PySpark (ver pyspark/sql/__init__.py).\"\"\"\nfrom .sql import SparkSession, Row  # noqa: F401\n\n__version__ = \"4.2.1-mini\"\n\n\nclass StorageLevel:\n    MEMORY_ONLY = \"MEMORY_ONLY\"\n    MEMORY_AND_DISK = \"MEMORY_AND_DISK\"\n    DISK_ONLY = \"DISK_ONLY\"\n    MEMORY_ONLY_SER = \"MEMORY_ONLY_SER\"\n    MEMORY_AND_DISK_SER = \"MEMORY_AND_DISK_SER\"\n    OFF_HEAP = \"OFF_HEAP\"\n\n\nclass SparkConf:\n    def __init__(self):\n        self._d = {}\n\n    def setAppName(self, n):\n        self._d[\"spark.app.name\"] = n\n        return self\n\n    def setMaster(self, m):\n        return self\n\n    def set(self, k, v):\n        self._d[k] = v\n        return self\n\n\nclass SparkContext:\n    @staticmethod\n    def getOrCreate(conf=None):\n        return SparkSession.builder.getOrCreate().sparkContext\n","pyspark/errors/__init__.py":"from ..sql import AnalysisException  # noqa: F401\n\nPySparkException = Exception\n","pyspark/sql/__init__.py":"\"\"\"\nmini-Spark: un simulador educativo de la API de PySpark escrito en Python puro.\n\nImplementa un subconjunto amplio de pyspark.sql para que puedas practicar la\nsintaxis en el navegador. NO es Spark real: no hay ejecutores, ni particiones\nreales, ni optimizador Catalyst. Para producción usa Spark/Databricks.\n\"\"\"\nimport datetime as _dt\nimport re as _re\nimport sqlite3 as _sqlite3\n\n__all__ = [\"SparkSession\", \"DataFrame\", \"Column\", \"Row\", \"Window\", \"functions\", \"types\"]\n\n_CATALOG = {}        # tablas registradas (saveAsTable / tablas de ejemplo)\n_TEMP_VIEWS = {}     # vistas temporales\n_FILES = {}          # \"sistema de archivos\" virtual: ruta -> DataFrame\n_RAW = {}            # tablas de ejemplo sin convertir (se convierten al primer uso)\n_CACHE = {}          # tablas de ejemplo ya convertidas\n\n\ndef _lazy_get(name):\n    \"\"\"Devuelve una tabla del catálogo, convirtiendo las de ejemplo solo cuando se usan.\"\"\"\n    if name in _CATALOG:\n        return _CATALOG[name]\n    if name in _CACHE:\n        return _CACHE[name]\n    if name in _RAW:\n        _CACHE[name] = _load_sample_tables({name: _RAW[name]})[name]\n        return _CACHE[name]\n    return None\n\n\ndef _all_table_names():\n    return set(_CATALOG) | set(_RAW)\n\n\nclass AnalysisException(Exception):\n    pass\n\n\n# --------------------------------------------------------------------------- Row\nclass Row(tuple):\n    def __new__(cls, *args, **kwargs):\n        if kwargs and not args:\n            r = tuple.__new__(cls, kwargs.values())\n            r.__fields__ = list(kwargs.keys())\n            return r\n        r = tuple.__new__(cls, args)\n        r.__fields__ = None\n        return r\n\n    def __getattr__(self, item):\n        f = tuple.__getattribute__(self, \"__fields__\")\n        if f and item in f:\n            return self[f.index(item)]\n        raise AttributeError(item)\n\n    def __getitem__(self, item):\n        if isinstance(item, str):\n            f = tuple.__getattribute__(self, \"__fields__\")\n            if f and item in f:\n                return tuple.__getitem__(self, f.index(item))\n            raise ValueError(item)\n        return tuple.__getitem__(self, item)\n\n    def asDict(self):\n        return dict(zip(self.__fields__ or [], self))\n\n    def __repr__(self):\n        if self.__fields__:\n            return \"Row(\" + \", \".join(\"%s=%r\" % (k, v) for k, v in zip(self.__fields__, self)) + \")\"\n        return \"<Row(\" + \", \".join(repr(v) for v in self) + \")>\"\n\n\ndef _mkrow(names, values):\n    r = tuple.__new__(Row, values)\n    r.__fields__ = list(names)\n    return r\n\n\n# ------------------------------------------------------------------------- tipos\ndef _infer_type(v):\n    from . import types as T\n    if v is None:\n        return T.NullType()\n    if isinstance(v, bool):\n        return T.BooleanType()\n    if isinstance(v, int):\n        return T.LongType()\n    if isinstance(v, float):\n        return T.DoubleType()\n    if isinstance(v, _dt.datetime):\n        return T.TimestampType()\n    if isinstance(v, _dt.date):\n        return T.DateType()\n    if isinstance(v, (list, tuple)):\n        inner = next((x for x in v if x is not None), None)\n        return T.ArrayType(_infer_type(inner) if inner is not None else T.StringType())\n    if isinstance(v, dict):\n        return T.MapType(T.StringType(), T.StringType())\n    return T.StringType()\n\n\ndef _cast(v, typ):\n    from . import types as T\n    if v is None:\n        return None\n    if isinstance(typ, str):\n        typ = T._parse_type(typ)\n    try:\n        if isinstance(typ, (T.IntegerType, T.LongType, T.ShortType)):\n            if isinstance(v, str):\n                v = v.strip()\n                return int(float(v)) if v else None\n            return int(v)\n        if isinstance(typ, (T.DoubleType, T.FloatType, T.DecimalType)):\n            r = float(v)\n            if isinstance(typ, T.DecimalType):\n                r = round(r, typ.scale)\n            return r\n        if isinstance(typ, T.StringType):\n            if isinstance(v, bool):\n                return \"true\" if v else \"false\"\n            if isinstance(v, float) and v.is_integer():\n                return str(v)\n            return str(v)\n        if isinstance(typ, T.BooleanType):\n            if isinstance(v, str):\n                return v.strip().lower() in (\"true\", \"1\", \"t\", \"yes\", \"y\")\n            return bool(v)\n        if isinstance(typ, T.DateType):\n            return _to_date(v)\n        if isinstance(typ, T.TimestampType):\n            return _to_ts(v)\n    except (ValueError, TypeError):\n        return None\n    return v\n\n\ndef _to_date(v, fmt=None):\n    if v is None:\n        return None\n    if isinstance(v, _dt.datetime):\n        return v.date()\n    if isinstance(v, _dt.date):\n        return v\n    s = str(v).strip()\n    try:\n        if fmt:\n            return _dt.datetime.strptime(s, _java_fmt(fmt)).date()\n        return _dt.date.fromisoformat(s[:10])\n    except ValueError:\n        return None\n\n\ndef _to_ts(v, fmt=None):\n    if v is None:\n        return None\n    if isinstance(v, _dt.datetime):\n        return v\n    if isinstance(v, _dt.date):\n        return _dt.datetime(v.year, v.month, v.day)\n    s = str(v).strip().replace(\"T\", \" \")\n    try:\n        if fmt:\n            return _dt.datetime.strptime(s, _java_fmt(fmt))\n        return _dt.datetime.fromisoformat(s)\n    except ValueError:\n        return None\n\n\ndef _java_fmt(fmt):\n    rep = [(\"yyyy\", \"%Y\"), (\"yy\", \"%y\"), (\"MMMM\", \"%B\"), (\"MMM\", \"%b\"), (\"MM\", \"%m\"), (\"dd\", \"%d\"),\n           (\"HH\", \"%H\"), (\"mm\", \"%M\"), (\"ss\", \"%S\"), (\"EEEE\", \"%A\"), (\"EEE\", \"%a\")]\n    out = fmt\n    for a, b in rep:\n        out = out.replace(a, b)\n    return out\n\n\n# ------------------------------------------------------------------- expresiones\nclass Column:\n    \"\"\"Una expresión sobre columnas. Se evalúa de forma vectorizada.\"\"\"\n\n    def __init__(self, kind, name, children=(), fn=None, **kw):\n        self.kind = kind          # 'ref','lit','fn','agg','win','when','star','sort'\n        self._name = name\n        self.children = list(children)\n        self.fn = fn\n        self.kw = kw\n\n    # ---- nombres\n    def _out_name(self):\n        return self.kw.get(\"alias\", self._name)\n\n    def alias(self, name, **_):\n        c = Column(self.kind, self._name, self.children, self.fn, **self.kw)\n        c.kw[\"alias\"] = name\n        return c\n\n    name = alias\n\n    def __repr__(self):\n        return \"Column<'%s'>\" % self._name\n\n    def __bool__(self):\n        raise ValueError(\"No se puede convertir una Column en bool. Usa '&' en lugar de 'and', '|' en lugar de 'or' y '~' en lugar de 'not'. \"\n                         \"Recuerda poner paréntesis: (F.col('a') > 1) & (F.col('b') < 5)\")\n\n    __hash__ = object.__hash__\n\n    def __iter__(self):\n        raise TypeError(\"Column no es iterable\")\n\n    # ---- evaluación\n    def _has(self, kind):\n        return self.kind == kind or any(c._has(kind) for c in self.children if isinstance(c, Column))\n\n    def _eval(self, df):\n        \"\"\"Devuelve una lista con un valor por fila de df.\"\"\"\n        k = self.kind\n        if k == \"ref\":\n            idx, path = df._resolve_path(self._name, self.kw.get(\"df_id\"))\n            if path:\n                return [_get_path(r[idx], path) for r in df._rows]\n            return [r[idx] for r in df._rows]\n        if k == \"lit\":\n            return [self.kw[\"value\"]] * len(df._rows)\n        if k == \"fn\":\n            if self.kw.get(\"rowwise_df\"):\n                return self.fn(df, self.children)\n            vecs = [c._eval(df) for c in self.children]\n            if not vecs:\n                return [self.fn() for _ in df._rows]\n            return [self.fn(*vals) for vals in zip(*vecs)]\n        if k == \"when\":\n            n = len(df._rows)\n            out = [None] * n\n            done = [False] * n\n            for cond, val in self.kw[\"branches\"]:\n                cv = cond._eval(df)\n                vv = _as_col(val)._eval(df)\n                for i in range(n):\n                    if not done[i] and cv[i]:\n                        out[i] = vv[i]\n                        done[i] = True\n            if \"otherwise\" in self.kw:\n                ov = _as_col(self.kw[\"otherwise\"])._eval(df)\n                for i in range(n):\n                    if not done[i]:\n                        out[i] = ov[i]\n            return out\n        if k == \"win\":\n            if self.kw.get(\"spec\") is None:\n                raise AnalysisException(\"La función de ventana '%s' necesita .over(Window.partitionBy(...).orderBy(...))\" % self._name)\n            return _eval_window(self, df)\n        if k == \"sort\":\n            return self.children[0]._eval(df)\n        if k == \"agg\":\n            raise AnalysisException(\n                \"La función de agregación '%s' debe usarse dentro de groupBy(...).agg(...), df.agg(...) o con .over(ventana).\" % self._name)\n        raise AnalysisException(\"Expresión no soportada: %s\" % self._name)\n\n    def _eval_group(self, df):\n        \"\"\"Evalúa en contexto de agregación: df son las filas de un grupo -> un valor.\"\"\"\n        k = self.kind\n        if k == \"agg\":\n            vals = self.children[0]._eval(df) if self.children else [1] * len(df._rows)\n            return self.fn(vals)\n        if k == \"lit\":\n            return self.kw[\"value\"]\n        if k == \"ref\":\n            vals = self._eval(df)\n            return vals[0] if vals else None\n        if k == \"fn\":\n            if self.kw.get(\"rowwise_df\"):\n                vals = self.fn(df, self.children)\n                return vals[0] if vals else None\n            return self.fn(*[c._eval_group(df) for c in self.children])\n        if k == \"when\":\n            for cond, val in self.kw[\"branches\"]:\n                if cond._eval_group(df):\n                    return _as_col(val)._eval_group(df)\n            return _as_col(self.kw.get(\"otherwise\"))._eval_group(df) if \"otherwise\" in self.kw else None\n        raise AnalysisException(\"Expresión no válida en agregación: %s\" % self._name)\n\n    # ---- operadores\n    def _bin(self, other, op, sym, reverse=False):\n        o = _as_col(other)\n        a, b = (o, self) if reverse else (self, o)\n\n        def f(x, y):\n            if x is None or y is None:\n                return None\n            if type(x) is not type(y):\n                x, y = _coerce(x, y)\n            try:\n                return op(x, y)\n            except ZeroDivisionError:\n                return None\n            except TypeError:\n                raise AnalysisException(\"No se puede aplicar '%s' entre %r y %r\" % (sym, x, y))\n        return Column(\"fn\", \"(%s %s %s)\" % (a._name, sym, b._name), [a, b], f, op=sym)\n\n    def __add__(self, o): return self._bin(o, lambda x, y: x + y, \"+\")\n    def __radd__(self, o): return self._bin(o, lambda x, y: x + y, \"+\", True)\n    def __sub__(self, o): return self._bin(o, lambda x, y: x - y, \"-\")\n    def __rsub__(self, o): return self._bin(o, lambda x, y: x - y, \"-\", True)\n    def __mul__(self, o): return self._bin(o, lambda x, y: x * y, \"*\")\n    def __rmul__(self, o): return self._bin(o, lambda x, y: x * y, \"*\", True)\n    def __truediv__(self, o): return self._bin(o, lambda x, y: x / y, \"/\")\n    def __rtruediv__(self, o): return self._bin(o, lambda x, y: x / y, \"/\", True)\n    def __mod__(self, o): return self._bin(o, lambda x, y: x % y, \"%\")\n    def __pow__(self, o): return self._bin(o, lambda x, y: x ** y, \"**\")\n    def __eq__(self, o): return self._bin(o, lambda x, y: x == y, \"=\")\n    def __ne__(self, o): return self._bin(o, lambda x, y: x != y, \"!=\")\n    def __lt__(self, o): return self._bin(o, lambda x, y: x < y, \"<\")\n    def __le__(self, o): return self._bin(o, lambda x, y: x <= y, \"<=\")\n    def __gt__(self, o): return self._bin(o, lambda x, y: x > y, \">\")\n    def __ge__(self, o): return self._bin(o, lambda x, y: x >= y, \">=\")\n\n    def __neg__(self):\n        return Column(\"fn\", \"(- %s)\" % self._name, [self], lambda x: None if x is None else -x)\n\n    def __and__(self, o):\n        o = _as_col(o)\n\n        def f(x, y):\n            if x is False or y is False:\n                return False\n            if x is None or y is None:\n                return None\n            return bool(x and y)\n        return Column(\"fn\", \"(%s AND %s)\" % (self._name, o._name), [self, o], f, op=\"and\")\n\n    def __or__(self, o):\n        o = _as_col(o)\n\n        def f(x, y):\n            if x is True or y is True:\n                return True\n            if x is None or y is None:\n                return None\n            return bool(x or y)\n        return Column(\"fn\", \"(%s OR %s)\" % (self._name, o._name), [self, o], f)\n\n    def __invert__(self):\n        return Column(\"fn\", \"(NOT %s)\" % self._name, [self], lambda x: None if x is None else not x)\n\n    __rand__ = __and__\n    __ror__ = __or__\n\n    def eqNullSafe(self, o):\n        o = _as_col(o)\n        return Column(\"fn\", \"(%s <=> %s)\" % (self._name, o._name), [self, o], lambda x, y: x == y)\n\n    # ---- métodos\n    def isNull(self):\n        return Column(\"fn\", \"(%s IS NULL)\" % self._name, [self], lambda x: x is None)\n\n    def isNotNull(self):\n        return Column(\"fn\", \"(%s IS NOT NULL)\" % self._name, [self], lambda x: x is not None)\n\n    def isin(self, *vals):\n        if len(vals) == 1 and isinstance(vals[0], (list, tuple, set)):\n            vals = list(vals[0])\n        s = list(vals)\n        return Column(\"fn\", \"(%s IN (%s))\" % (self._name, \", \".join(map(str, s))), [self], lambda x: None if x is None else x in s)\n\n    def between(self, lo, hi):\n        return (self >= lo) & (self <= hi)\n\n    def like(self, pat):\n        rx = _like_to_regex(pat)\n        return Column(\"fn\", \"%s LIKE %s\" % (self._name, pat), [self], lambda x: None if x is None else bool(rx.match(str(x))))\n\n    def ilike(self, pat):\n        rx = _like_to_regex(pat, _re.I)\n        return Column(\"fn\", \"%s ILIKE %s\" % (self._name, pat), [self], lambda x: None if x is None else bool(rx.match(str(x))))\n\n    def rlike(self, pat):\n        rx = _re.compile(pat)\n        return Column(\"fn\", \"%s RLIKE %s\" % (self._name, pat), [self], lambda x: None if x is None else bool(rx.search(str(x))))\n\n    def contains(self, s):\n        o = _as_col(s)\n        return Column(\"fn\", \"contains(%s, %s)\" % (self._name, o._name), [self, o],\n                      lambda x, y: None if x is None or y is None else str(y) in str(x))\n\n    def startswith(self, s):\n        return Column(\"fn\", \"startswith(%s, %s)\" % (self._name, s), [self], lambda x: None if x is None else str(x).startswith(s))\n\n    def endswith(self, s):\n        return Column(\"fn\", \"endswith(%s, %s)\" % (self._name, s), [self], lambda x: None if x is None else str(x).endswith(s))\n\n    def substr(self, start, length):\n        return Column(\"fn\", \"substring(%s, %s, %s)\" % (self._name, start, length), [self],\n                      lambda x: None if x is None else str(x)[max(start - 1, 0):max(start - 1, 0) + length])\n\n    def cast(self, typ):\n        tname = typ if isinstance(typ, str) else typ.simpleString()\n        return Column(\"fn\", \"CAST(%s AS %s)\" % (self._name, tname.upper()), [self], lambda x: _cast(x, typ))\n\n    astype = cast\n\n    def desc(self):\n        return Column(\"sort\", self._name, [self], asc=False, nulls_first=False)\n\n    def asc(self):\n        return Column(\"sort\", self._name, [self], asc=True, nulls_first=True)\n\n    def desc_nulls_last(self): return Column(\"sort\", self._name, [self], asc=False, nulls_first=False)\n    def desc_nulls_first(self): return Column(\"sort\", self._name, [self], asc=False, nulls_first=True)\n    def asc_nulls_last(self): return Column(\"sort\", self._name, [self], asc=True, nulls_first=False)\n    def asc_nulls_first(self): return Column(\"sort\", self._name, [self], asc=True, nulls_first=True)\n\n    def when(self, cond, val):\n        if self.kind != \"when\":\n            raise AnalysisException(\"when() solo puede encadenarse después de F.when(...)\")\n        c = Column(\"when\", self._name, [], None, branches=self.kw[\"branches\"] + [(cond, val)])\n        return c\n\n    def otherwise(self, val):\n        if self.kind != \"when\":\n            raise AnalysisException(\"otherwise() solo puede usarse después de F.when(...)\")\n        kw = dict(self.kw)\n        kw[\"otherwise\"] = val\n        return Column(\"when\", self._name, [], None, **kw)\n\n    def over(self, window=None):\n        from .window import WindowSpec\n        w = window or WindowSpec()\n        if self.kind == \"agg\":\n            return Column(\"win\", \"%s OVER (...)\" % self._name, self.children, None, agg=self, spec=w)\n        if self.kind == \"win\":\n            return Column(\"win\", self._name, self.children, None, func=self.kw.get(\"func\"), args=self.kw.get(\"args\"), spec=w)\n        raise AnalysisException(\"over() solo aplica a funciones de agregación o de ventana (row_number, rank, lag...)\")\n\n    def getItem(self, key):\n        return Column(\"fn\", \"%s[%s]\" % (self._name, key), [self], lambda x: _get_item(x, key))\n\n    def __getitem__(self, key):\n        return self.getItem(key)\n\n    def getField(self, name):\n        return self.getItem(name)\n\n\ndef _get_item(x, key):\n    if x is None:\n        return None\n    try:\n        return x[key]\n    except (IndexError, KeyError, TypeError):\n        return None\n\n\ndef _coerce(x, y):\n    \"\"\"Conversión implícita al comparar tipos distintos, como hace Spark.\"\"\"\n    def conv(v, ref):\n        if isinstance(v, str):\n            if isinstance(ref, _dt.datetime):\n                return _to_ts(v)\n            if isinstance(ref, _dt.date):\n                return _to_date(v)\n            if isinstance(ref, bool):\n                return v.strip().lower() == \"true\"\n            if isinstance(ref, (int, float)):\n                try:\n                    return float(v)\n                except ValueError:\n                    return v\n        if isinstance(v, _dt.datetime) and type(ref) is _dt.date:\n            return v.date()\n        return v\n    return conv(x, y), conv(y, x)\n\n\ndef _get_path(v, path):\n    for p in path:\n        if v is None:\n            return None\n        try:\n            v = v[p]\n        except (KeyError, IndexError, TypeError, ValueError):\n            raise AnalysisException(\"El campo '%s' no existe en el struct\" % p)\n    return v\n\n\ndef _like_to_regex(pat, flags=0):\n    out = \"\"\n    for ch in pat:\n        if ch == \"%\":\n            out += \".*\"\n        elif ch == \"_\":\n            out += \".\"\n        else:\n            out += _re.escape(ch)\n    return _re.compile(\"^\" + out + \"$\", flags | _re.S)\n\n\ndef _lit(v):\n    c = Column(\"lit\", \"NULL\" if v is None else (str(v).lower() if isinstance(v, bool) else str(v)))\n    c.kw[\"value\"] = v\n    return c\n\n\ndef _as_col(x):\n    if isinstance(x, Column):\n        return x\n    return _lit(x)\n\n\ndef _col(name, df_id=None):\n    if isinstance(name, Column):\n        return name\n    if name == \"*\":\n        return Column(\"star\", \"*\")\n    c = Column(\"ref\", name)\n    if df_id is not None:\n        c.kw[\"df_id\"] = df_id\n    return c\n\n\n# ----------------------------------------------------------------------- ventanas\ndef _sort_key_fn(sort_specs, df):\n    \"\"\"Devuelve una función índice -> clave de orden y un comparador estable.\"\"\"\n    cols = []\n    for s in sort_specs:\n        if s.kind == \"sort\":\n            cols.append((s.children[0]._eval(df), s.kw[\"asc\"], s.kw[\"nulls_first\"]))\n        else:\n            cols.append((s._eval(df), True, True))\n    return cols\n\n\ndef _order_indices(idxs, cols):\n    import functools\n\n    def cmp(i, j):\n        for vals, asc, nulls_first in cols:\n            a, b = vals[i], vals[j]\n            if a == b:\n                continue\n            if a is None:\n                return -1 if nulls_first else 1\n            if b is None:\n                return 1 if nulls_first else -1\n            try:\n                r = -1 if a < b else 1\n            except TypeError:\n                r = -1 if str(a) < str(b) else 1\n            return r if asc else -r\n        return 0\n    return sorted(idxs, key=functools.cmp_to_key(cmp))\n\n\ndef _eval_window(col, df):\n    spec = col.kw[\"spec\"]\n    n = len(df._rows)\n    part_vecs = [_as_col(p)._eval(df) for p in spec._partition]\n    groups = {}\n    for i in range(n):\n        key = tuple(_hashable(v[i]) for v in part_vecs)\n        groups.setdefault(key, []).append(i)\n    order_cols = _sort_key_fn([_sortable(o) for o in spec._order], df) if spec._order else []\n    out = [None] * n\n    agg = col.kw.get(\"agg\")\n    func = col.kw.get(\"func\")\n    args = col.kw.get(\"args\") or []\n    for idxs in groups.values():\n        ordered = _order_indices(idxs, order_cols) if order_cols else list(idxs)\n        okeys = [tuple(_hashable(c[0][i]) for c in order_cols) for i in ordered]\n        if func is not None:\n            if func in (\"row_number\", \"rank\", \"dense_rank\", \"percent_rank\", \"ntile\", \"cume_dist\"):\n                rank = dense = 0\n                prev = object()\n                m = len(ordered)\n                for pos, i in enumerate(ordered):\n                    if okeys[pos] != prev:\n                        rank = pos + 1\n                        dense += 1\n                        prev = okeys[pos]\n                    if func == \"row_number\":\n                        out[i] = pos + 1\n                    elif func == \"rank\":\n                        out[i] = rank\n                    elif func == \"dense_rank\":\n                        out[i] = dense\n                    elif func == \"percent_rank\":\n                        out[i] = 0.0 if m == 1 else (rank - 1) / (m - 1)\n                    elif func == \"ntile\":\n                        k = args[0]\n                        out[i] = pos * k // m + 1\n                    elif func == \"cume_dist\":\n                        last = max(p for p in range(m) if okeys[p] == okeys[pos])\n                        out[i] = (last + 1) / m\n            elif func in (\"lag\", \"lead\"):\n                vals = args[0]._eval(df)\n                off = args[1] if len(args) > 1 else 1\n                default = args[2] if len(args) > 2 else None\n                for pos, i in enumerate(ordered):\n                    j = pos - off if func == \"lag\" else pos + off\n                    out[i] = vals[ordered[j]] if 0 <= j < len(ordered) else default\n            elif func in (\"first_value\", \"last_value\"):\n                vals = args[0]._eval(df)\n                for pos, i in enumerate(ordered):\n                    if func == \"first_value\":\n                        out[i] = vals[ordered[0]]\n                    else:\n                        out[i] = vals[ordered[pos]] if spec._order and spec._frame is None else vals[ordered[-1]]\n            continue\n        # agregación sobre ventana\n        vals = agg.children[0]._eval(df) if agg.children else [1] * n\n        frame = spec._frame\n        m = len(ordered)\n        for pos, i in enumerate(ordered):\n            if frame is not None:\n                kind, lo, hi = frame\n                if kind == \"rows\":\n                    a = 0 if lo is None else max(0, pos + lo)\n                    b = m - 1 if hi is None else min(m - 1, pos + hi)\n                    sel = ordered[a:b + 1]\n                else:  # rangeBetween sobre valores del orden (solo un campo numérico)\n                    ov = order_cols[0][0]\n                    cur = ov[i]\n                    sel = [j for j in ordered if (lo is None or ov[j] >= cur + lo) and (hi is None or ov[j] <= cur + hi)]\n            elif spec._order:\n                # por defecto: RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW (incluye empates)\n                last = pos\n                while last + 1 < m and okeys[last + 1] == okeys[pos]:\n                    last += 1\n                sel = ordered[:last + 1]\n            else:\n                sel = ordered\n            out[i] = agg.fn([vals[j] for j in sel])\n    return out\n\n\ndef _sortable(o):\n    if isinstance(o, Column):\n        return o\n    return _col(o)\n\n\ndef _hashable(v):\n    if isinstance(v, list):\n        return tuple(_hashable(x) for x in v)\n    if isinstance(v, dict):\n        return tuple(sorted(v.items()))\n    return v\n\n\n# ---------------------------------------------------------------------- DataFrame\nclass _Field:\n    __slots__ = (\"name\", \"quals\")\n\n    def __init__(self, name, quals=()):\n        self.name = name\n        self.quals = set(quals)\n\n\n_df_counter = [0]\n\n\nclass DataFrame:\n    def __init__(self, fields, rows, session=None, schema_types=None):\n        _df_counter[0] += 1\n        self._id = _df_counter[0]\n        self._fields = [_Field(f.name, f.quals) if isinstance(f, _Field) else _Field(f) for f in fields]\n        for f in self._fields:\n            f.quals.add(self._id)\n        self._rows = [tuple(r) for r in rows]\n        self._session = session\n        self._types = schema_types\n        self._partitions = 8\n        self._cached = False\n\n    # ---- utilidades internas\n    def _resolve(self, name, df_id=None):\n        qual = None\n        if df_id is None and \".\" in name and name not in [f.name for f in self._fields]:\n            qual, name = name.split(\".\", 1)\n        name = name.strip(\"`\")\n        matches = [i for i, f in enumerate(self._fields) if f.name == name and\n                   (df_id is None or df_id in f.quals) and (qual is None or qual in f.quals)]\n        if not matches:\n            matches_ci = [i for i, f in enumerate(self._fields) if f.name.lower() == name.lower() and\n                          (df_id is None or df_id in f.quals) and (qual is None or qual in f.quals)]\n            matches = matches_ci\n        if not matches:\n            raise AnalysisException(\"[UNRESOLVED_COLUMN] No se encuentra la columna '%s'. Columnas disponibles: %s\"\n                                    % ((qual + \".\" if qual else \"\") + name, [f.name for f in self._fields]))\n        if len(matches) > 1:\n            raise AnalysisException(\"[AMBIGUOUS_REFERENCE] La columna '%s' es ambigua (aparece %d veces). \"\n                                    \"Usa df1['%s'] / df1.alias('a') + F.col('a.%s') o renómbrala antes del join.\"\n                                    % (name, len(matches), name, name))\n        return matches[0]\n\n    def _resolve_path(self, name, df_id=None):\n        \"\"\"Como _resolve, pero acepta 'struct.campo' y devuelve (índice, [campos]).\"\"\"\n        try:\n            return self._resolve(name, df_id), []\n        except AnalysisException:\n            if \".\" not in name:\n                raise\n            parts = name.split(\".\")\n            for k in range(len(parts) - 1, 0, -1):\n                try:\n                    idx = self._resolve(\".\".join(parts[:k]), df_id)\n                except AnalysisException:\n                    continue\n                return idx, parts[k:]\n            raise\n\n    def _new(self, fields, rows, types=None):\n        df = DataFrame(fields, rows, self._session, types)\n        df._partitions = self._partitions\n        return df\n\n    def _expand(self, cols):\n        out = []\n        for c in cols:\n            if isinstance(c, (list, tuple)):\n                out.extend(self._expand(c))\n            elif isinstance(c, str):\n                if c == \"*\":\n                    out.extend(Column(\"ref\", f.name, df_id=None, idx=i) for i, f in enumerate(self._fields))\n                elif c.endswith(\".*\"):\n                    q = c[:-2]\n                    quals = [Column(\"ref\", f.name, idx=i) for i, f in enumerate(self._fields) if q in f.quals]\n                    if not quals and q in self.columns:\n                        i = self.columns.index(q)\n                        sample = next((r[i] for r in self._rows if r[i] is not None), None)\n                        names = list(getattr(sample, \"__fields__\", None) or (sample.keys() if isinstance(sample, dict) else []))\n                        quals = [_col(\"%s.%s\" % (q, n)) for n in names]\n                    out.extend(quals)\n                else:\n                    out.append(_col(c))\n            elif isinstance(c, Column) and c.kind == \"star\":\n                out.extend(Column(\"ref\", f.name, idx=i) for i, f in enumerate(self._fields))\n            else:\n                out.append(c)\n        return out\n\n    def _eval_col(self, c):\n        if c.kind == \"ref\" and \"idx\" in c.kw:\n            i = c.kw[\"idx\"]\n            return [r[i] for r in self._rows]\n        if c.kind == \"fn\" and c.kw.get(\"explode\"):\n            return None\n        return c._eval(self)\n\n    def __getitem__(self, item):\n        if isinstance(item, str):\n            self._resolve(item)\n            return _col(item, self._id)\n        if isinstance(item, Column):\n            return self.filter(item)\n        if isinstance(item, int):\n            return _col(self._fields[item].name, self._id)\n        if isinstance(item, (list, tuple)):\n            return self.select(*item)\n        raise TypeError(item)\n\n    def __getattr__(self, item):\n        if item.startswith(\"_\"):\n            raise AttributeError(item)\n        if any(f.name == item for f in self._fields):\n            return self[item]\n        raise AttributeError(\"'DataFrame' no tiene el atributo '%s'\" % item)\n\n    # ---- propiedades\n    @property\n    def sparkSession(self):\n        return self._session or SparkSession._active or SparkSession.builder.getOrCreate()\n\n    @property\n    def columns(self):\n        return [f.name for f in self._fields]\n\n    @property\n    def schema(self):\n        from . import types as T\n        fields = []\n        for i, f in enumerate(self._fields):\n            fields.append(T.StructField(f.name, self._col_type(i), True))\n        return T.StructType(fields)\n\n    def _col_type(self, i):\n        from . import types as T\n        if self._types and i < len(self._types) and self._types[i] is not None:\n            return self._types[i]\n        for r in self._rows:\n            if r[i] is not None:\n                t = _infer_type(r[i])\n                if isinstance(t, T.LongType) and isinstance(r[i], int):\n                    return t\n                return t\n        return T.StringType()\n\n    @property\n    def dtypes(self):\n        return [(f.name, self._col_type(i).simpleString()) for i, f in enumerate(self._fields)]\n\n    @property\n    def write(self):\n        return DataFrameWriter(self)\n\n    @property\n    def na(self):\n        return _NA(self)\n\n    @property\n    def rdd(self):\n        return _RDD(self)\n\n    @property\n    def isStreaming(self):\n        return False\n\n    # ---- transformaciones\n    def select(self, *cols):\n        cols = self._expand(cols)\n        explode_cols = [c for c in cols if isinstance(c, Column) and c.kw.get(\"explode\")]\n        if any(c._has(\"agg\") and c.kind != \"win\" and not _only_in_window(c) for c in cols):\n            return self.agg(*cols)\n        fields, vecs, types = [], [], []\n        for c in cols:\n            if c.kind == \"ref\" and \"idx\" in c.kw:\n                f = self._fields[c.kw[\"idx\"]]\n                fields.append(_Field(f.name, f.quals))\n                types.append(self._types[c.kw[\"idx\"]] if self._types else None)\n                vecs.append(self._eval_col(c))\n            elif c.kind == \"ref\":\n                i, path = self._resolve_path(c._name, c.kw.get(\"df_id\"))\n                f = self._fields[i]\n                aliased = \"alias\" in c.kw\n                if path:\n                    fields.append(_Field(c.kw[\"alias\"] if aliased else path[-1]))\n                    types.append(None)\n                    vecs.append([_get_path(r[i], path) for r in self._rows])\n                    continue\n                fields.append(_Field(c.kw[\"alias\"] if aliased else f.name, () if aliased else f.quals))\n                types.append(self._types[i] if self._types and not aliased else None)\n                vecs.append([r[i] for r in self._rows])\n            elif c.kw.get(\"explode\"):\n                fields.append(_Field(c.kw.get(\"alias\", \"col\")))\n                types.append(None)\n                vecs.append(c.children[0]._eval(self))\n            else:\n                fields.append(_Field(c._out_name()))\n                types.append(c.kw.get(\"dtype\"))\n                vecs.append(c._eval(self))\n        n = len(self._rows)\n        rows = [tuple(v[i] for v in vecs) for i in range(n)]\n        if explode_cols:\n            pos = [k for k, c in enumerate(cols) if c.kw.get(\"explode\")][0]\n            outer = cols[pos].kw.get(\"outer\")\n            new_rows = []\n            for r in rows:\n                arr = r[pos]\n                if isinstance(arr, dict):\n                    arr = list(arr.items())\n                if not arr:\n                    if outer:\n                        new_rows.append(r[:pos] + (None,) + r[pos + 1:])\n                    continue\n                for x in arr:\n                    new_rows.append(r[:pos] + (x,) + r[pos + 1:])\n            rows = new_rows\n        return self._new(fields, rows, types)\n\n    def selectExpr(self, *exprs):\n        return self.sparkSession._sql_on(self, \"SELECT %s FROM __t\" % \", \".join(exprs))\n\n    def filter(self, cond):\n        if isinstance(cond, str):\n            return self.sparkSession._sql_on(self, \"SELECT * FROM __t WHERE %s\" % cond, keep_types=True)\n        if cond._has(\"agg\"):\n            raise AnalysisException(\"No se pueden usar agregaciones en filter/where. Agrupa primero y filtra después (equivale a HAVING).\")\n        vals = cond._eval(self)\n        rows = [r for r, v in zip(self._rows, vals) if v]\n        df = self._new(self._fields, rows, self._types)\n        df._fields = [_Field(f.name, f.quals) for f in self._fields]\n        df._id = self._id  # mantiene referencias df[\"col\"] válidas\n        return df\n\n    where = filter\n\n    def withColumn(self, name, col):\n        if not isinstance(col, Column):\n            raise TypeError(\"withColumn espera una Column. ¿Olvidaste F.lit(%r)?\" % (col,))\n        if col.kw.get(\"explode\"):\n            cols = [_col(c) for c in self.columns if c != name]\n            return self.select(*(cols + [col.alias(name)]))\n        if col._has(\"agg\") and not _only_in_window(col):\n            raise AnalysisException(\"withColumn no admite agregaciones sin ventana. Usa groupBy().agg() o .over(Window...)\")\n        vals = col._eval(self)\n        names = self.columns\n        if name in names:\n            i = names.index(name)\n            rows = [r[:i] + (v,) + r[i + 1:] for r, v in zip(self._rows, vals)]\n            types = list(self._types) if self._types else None\n            if types:\n                types[i] = col.kw.get(\"dtype\")\n            df = self._new([_Field(f.name, f.quals) for f in self._fields], rows, types)\n        else:\n            rows = [r + (v,) for r, v in zip(self._rows, vals)]\n            types = (list(self._types) + [col.kw.get(\"dtype\")]) if self._types else None\n            df = self._new([_Field(f.name, f.quals) for f in self._fields] + [_Field(name)], rows, types)\n        df._id = self._id\n        for f in df._fields:\n            f.quals.add(self._id)\n        return df\n\n    def withColumns(self, mapping):\n        df = self\n        for k, v in mapping.items():\n            df = df.withColumn(k, v)\n        return df\n\n    def withColumnRenamed(self, old, new):\n        fields = [_Field(new if f.name == old else f.name, f.quals) for f in self._fields]\n        df = self._new(fields, self._rows, self._types)\n        return df\n\n    def withColumnsRenamed(self, mapping):\n        df = self\n        for k, v in mapping.items():\n            df = df.withColumnRenamed(k, v)\n        return df\n\n    def toDF(self, *names):\n        if len(names) != len(self._fields):\n            raise AnalysisException(\"toDF esperaba %d nombres\" % len(self._fields))\n        return self._new(list(names), self._rows, self._types)\n\n    def drop(self, *cols):\n        idxs = set()\n        for c in cols:\n            if isinstance(c, Column):\n                try:\n                    idxs.add(self._resolve(c._name, c.kw.get(\"df_id\")))\n                except AnalysisException:\n                    pass\n            else:\n                idxs.update(i for i, f in enumerate(self._fields) if f.name == c)\n        keep = [i for i in range(len(self._fields)) if i not in idxs]\n        return self._new([self._fields[i] for i in keep], [tuple(r[i] for i in keep) for r in self._rows],\n                         [self._types[i] for i in keep] if self._types else None)\n\n    def alias(self, name):\n        df = self._new([_Field(f.name, set(f.quals) | {name}) for f in self._fields], self._rows, self._types)\n        df._id = self._id\n        return df\n\n    def distinct(self):\n        seen, rows = set(), []\n        for r in self._rows:\n            k = tuple(_hashable(v) for v in r)\n            if k not in seen:\n                seen.add(k)\n                rows.append(r)\n        return self._new(self._fields, rows, self._types)\n\n    def dropDuplicates(self, subset=None):\n        if not subset:\n            return self.distinct()\n        if isinstance(subset, str):\n            subset = [subset]\n        idx = [self._resolve(c) for c in subset]\n        seen, rows = set(), []\n        for r in self._rows:\n            k = tuple(_hashable(r[i]) for i in idx)\n            if k not in seen:\n                seen.add(k)\n                rows.append(r)\n        return self._new(self._fields, rows, self._types)\n\n    drop_duplicates = dropDuplicates\n\n    def orderBy(self, *cols, ascending=None):\n        cols = [c for c in self._expand(cols)]\n        if ascending is not None:\n            asc = ascending if isinstance(ascending, list) else [ascending] * len(cols)\n            cols = [c.asc() if a else c.desc() for c, a in zip(cols, asc)]\n        specs = _sort_key_fn(cols, self)\n        order = _order_indices(range(len(self._rows)), specs)\n        df = self._new(self._fields, [self._rows[i] for i in order], self._types)\n        df._id = self._id\n        return df\n\n    sort = orderBy\n\n    def sortWithinPartitions(self, *cols, **kw):\n        return self.orderBy(*cols, **kw)\n\n    def limit(self, n):\n        return self._new(self._fields, self._rows[:n], self._types)\n\n    def offset(self, n):\n        return self._new(self._fields, self._rows[n:], self._types)\n\n    def groupBy(self, *cols):\n        return GroupedData(self, self._expand(cols))\n\n    groupby = groupBy\n\n    def rollup(self, *cols):\n        return GroupedData(self, self._expand(cols), mode=\"rollup\")\n\n    def cube(self, *cols):\n        return GroupedData(self, self._expand(cols), mode=\"cube\")\n\n    def agg(self, *exprs):\n        return GroupedData(self, []).agg(*exprs)\n\n    def join(self, other, on=None, how=\"inner\"):\n        how = (how or \"inner\").lower().replace(\"_\", \"\")\n        aliases = {\"inner\": \"inner\", \"left\": \"left\", \"leftouter\": \"left\", \"right\": \"right\", \"rightouter\": \"right\",\n                   \"outer\": \"full\", \"full\": \"full\", \"fullouter\": \"full\", \"leftsemi\": \"semi\", \"semi\": \"semi\",\n                   \"leftanti\": \"anti\", \"anti\": \"anti\", \"cross\": \"cross\"}\n        if how not in aliases:\n            raise AnalysisException(\"Tipo de join no soportado: %s\" % how)\n        how = aliases[how]\n        nl, nr = len(self._fields), len(other._fields)\n        using = None\n        if on is None:\n            pairs = None\n        elif isinstance(on, str):\n            using = [on]\n        elif isinstance(on, (list, tuple)) and all(isinstance(x, str) for x in on):\n            using = list(on)\n        elif isinstance(on, (list, tuple)):\n            cond = on[0]\n            for x in on[1:]:\n                cond = cond & x\n            on = cond\n        combined_fields = [_Field(f.name, f.quals) for f in self._fields] + [_Field(f.name, f.quals) for f in other._fields]\n        tmp = DataFrame(combined_fields, [], self._session)\n\n        if using is not None:\n            li = [self._resolve(c) for c in using]\n            ri = [other._resolve(c) for c in using]\n            index = {}\n            for j, r in enumerate(other._rows):\n                k = tuple(r[i] for i in ri)\n                if None in k:\n                    continue\n                index.setdefault(k, []).append(j)\n\n            def matches(lrow):\n                k = tuple(lrow[i] for i in li)\n                return [] if None in k else index.get(k, [])\n        elif on is None:\n            def matches(lrow):\n                return range(len(other._rows))\n        else:\n            cond = on\n\n            def matches_all():\n                res = {}\n                # evaluación por bloques: producto cartesiano filtrado\n                eq = _equi_keys(cond, self, other)\n                if eq:\n                    lk, rk = eq\n                    lv = [c._eval(self) for c in lk]\n                    rv = [c._eval(other) for c in rk]\n                    idx = {}\n                    for j in range(len(other._rows)):\n                        k = tuple(v[j] for v in rv)\n                        if None not in k:\n                            idx.setdefault(k, []).append(j)\n                    cand = {i: idx.get(tuple(v[i] for v in lv), []) for i in range(len(self._rows))}\n                else:\n                    cand = {i: range(len(other._rows)) for i in range(len(self._rows))}\n                pairs_rows = []\n                pairs_idx = []\n                for i, js in cand.items():\n                    for j in js:\n                        pairs_rows.append(self._rows[i] + other._rows[j])\n                        pairs_idx.append((i, j))\n                tmp._rows = pairs_rows\n                ok = cond._eval(tmp) if pairs_rows else []\n                for (i, j), v in zip(pairs_idx, ok):\n                    if v:\n                        res.setdefault(i, []).append(j)\n                return res\n            precomputed = matches_all()\n\n            def matches(lrow, _i=[0]):\n                return precomputed.get(lrow, [])\n\n        rows = []\n        matched_right = set()\n        null_r = (None,) * nr\n        null_l = (None,) * nl\n        for i, lr in enumerate(self._rows):\n            js = matches(i if (using is None and on is not None) else lr)\n            js = list(js)\n            if how == \"semi\":\n                if js:\n                    rows.append(lr)\n                continue\n            if how == \"anti\":\n                if not js:\n                    rows.append(lr)\n                continue\n            for j in js:\n                rows.append(lr + other._rows[j])\n                matched_right.add(j)\n            if not js and how in (\"left\", \"full\"):\n                rows.append(lr + null_r)\n        if how in (\"right\", \"full\"):\n            for j, rr in enumerate(other._rows):\n                if j not in matched_right:\n                    rows.append(null_l + rr)\n        if how in (\"semi\", \"anti\"):\n            return self._new(self._fields, rows, self._types)\n\n        fields = combined_fields\n        types = None\n        if using is not None:\n            # las columnas del USING aparecen una sola vez (coalesce para outer joins)\n            li = [self._resolve(c) for c in using]\n            ri = [other._resolve(c) for c in using]\n            drop_r = set(nl + i for i in ri)\n            new_rows = []\n            for r in rows:\n                key = []\n                for a, b in zip(li, ri):\n                    key.append(r[a] if r[a] is not None else r[nl + b])\n                rest = [r[k] for k in range(nl + nr) if k not in drop_r and k not in li]\n                new_rows.append(tuple(key) + tuple(rest))\n            keep_fields = [fields[k] for k in range(nl + nr) if k not in drop_r and k not in li]\n            key_fields = [_Field(self._fields[a].name, self._fields[a].quals | other._fields[b].quals) for a, b in zip(li, ri)]\n            fields = key_fields + keep_fields\n            rows = new_rows\n        return self._new(fields, rows, types)\n\n    def crossJoin(self, other):\n        return self.join(other, how=\"cross\")\n\n    def union(self, other):\n        if len(self._fields) != len(other._fields):\n            raise AnalysisException(\"union requiere el mismo número de columnas (%d vs %d)\" % (len(self._fields), len(other._fields)))\n        return self._new(self._fields, self._rows + other._rows, self._types)\n\n    unionAll = union\n\n    def unionByName(self, other, allowMissingColumns=False):\n        names = self.columns\n        oth = other.columns\n        missing = [c for c in names if c not in oth]\n        if missing and not allowMissingColumns:\n            raise AnalysisException(\"unionByName: faltan columnas en el segundo DataFrame: %s\" % missing)\n        extra = [c for c in oth if c not in names]\n        if extra and not allowMissingColumns:\n            raise AnalysisException(\"unionByName: columnas extra en el segundo DataFrame: %s\" % extra)\n        allnames = names + extra\n        rows = [r + (None,) * len(extra) for r in self._rows]\n        for r in other._rows:\n            d = dict(zip(oth, r))\n            rows.append(tuple(d.get(c) for c in allnames))\n        return self._new(allnames, rows)\n\n    def intersect(self, other):\n        s = set(other._rows)\n        return self._new(self._fields, [r for r in self.distinct()._rows if r in s])\n\n    def subtract(self, other):\n        s = set(other._rows)\n        return self._new(self._fields, [r for r in self.distinct()._rows if r not in s])\n\n    exceptAll = subtract\n\n    def fillna(self, value, subset=None):\n        return self.na.fill(value, subset)\n\n    def dropna(self, how=\"any\", thresh=None, subset=None):\n        return self.na.drop(how, thresh, subset)\n\n    def replace(self, to_replace, value=None, subset=None):\n        return self.na.replace(to_replace, value, subset)\n\n    def sample(self, withReplacement=None, fraction=None, seed=None):\n        import random\n        if isinstance(withReplacement, float):\n            fraction, withReplacement = withReplacement, False\n        rnd = random.Random(seed if seed is not None else 42)\n        return self._new(self._fields, [r for r in self._rows if rnd.random() < fraction], self._types)\n\n    def randomSplit(self, weights, seed=None):\n        import random\n        rnd = random.Random(seed if seed is not None else 42)\n        total = sum(weights)\n        cuts = []\n        acc = 0\n        for w in weights:\n            acc += w / total\n            cuts.append(acc)\n        parts = [[] for _ in weights]\n        for r in self._rows:\n            x = rnd.random()\n            for k, c in enumerate(cuts):\n                if x <= c:\n                    parts[k].append(r)\n                    break\n        return [self._new(self._fields, p, self._types) for p in parts]\n\n    # ---- particiones y caché (simuladas)\n    def repartition(self, n=None, *cols):\n        df = self._new(self._fields, self._rows, self._types)\n        if isinstance(n, int):\n            df._partitions = n\n        else:\n            df._partitions = 200\n        return df\n\n    def coalesce(self, n):\n        df = self._new(self._fields, self._rows, self._types)\n        df._partitions = min(n, self._partitions)\n        return df\n\n    def cache(self):\n        self._cached = True\n        return self\n\n    def persist(self, *a):\n        return self.cache()\n\n    def unpersist(self, *a):\n        self._cached = False\n        return self\n\n    def checkpoint(self, *a):\n        return self\n\n    def localCheckpoint(self, *a):\n        return self\n\n    def hint(self, *a):\n        return self\n\n    def explain(self, extended=False, mode=None):\n        print(\"== Physical Plan (simulado por mini-Spark) ==\")\n        print(\"*(1) Project %s\" % self.columns)\n        print(\"+- *(1) Scan ExistingRDD [%d filas, %d particiones]\" % (len(self._rows), self._partitions))\n        print(\"(En Spark real verías Exchange (shuffle), BroadcastHashJoin, SortMergeJoin, etc.)\")\n\n    def createOrReplaceTempView(self, name):\n        _TEMP_VIEWS[name.lower()] = self\n\n    createTempView = createOrReplaceTempView\n    registerTempTable = createOrReplaceTempView\n\n    def createOrReplaceGlobalTempView(self, name):\n        _TEMP_VIEWS[\"global_temp.\" + name.lower()] = self\n\n    # ---- acciones\n    def count(self):\n        return len(self._rows)\n\n    def collect(self):\n        names = self.columns\n        return [_mkrow(names, r) for r in self._rows]\n\n    def take(self, n):\n        return self.limit(n).collect()\n\n    def head(self, n=None):\n        if n is None:\n            r = self.take(1)\n            return r[0] if r else None\n        return self.take(n)\n\n    def first(self):\n        return self.head()\n\n    def tail(self, n):\n        names = self.columns\n        return [_mkrow(names, r) for r in self._rows[-n:]]\n\n    def isEmpty(self):\n        return len(self._rows) == 0\n\n    def toLocalIterator(self):\n        return iter(self.collect())\n\n    def foreach(self, f):\n        for r in self.collect():\n            f(r)\n\n    def toPandas(self):\n        try:\n            import pandas as pd\n        except ImportError:\n            raise ImportError(\"pandas no está cargado en este simulador; usa .collect() o .show()\")\n        return pd.DataFrame(self._rows, columns=self.columns)\n\n    def toJSON(self):\n        import json\n        return _RDDList([json.dumps(dict(zip(self.columns, [_jsonable(v) for v in r])), ensure_ascii=False) for r in self._rows])\n\n    def printSchema(self):\n        print(self.schema.treeString())\n\n    def describe(self, *cols):\n        cols = list(cols) or [c for i, c in enumerate(self.columns)]\n        stats = [\"count\", \"mean\", \"stddev\", \"min\", \"max\"]\n        out = []\n        for s in stats:\n            row = [s]\n            for c in cols:\n                vals = [v for v in self.select(c)._rows for v in v if v is not None]\n                nums = [v for v in vals if isinstance(v, (int, float)) and not isinstance(v, bool)]\n                if s == \"count\":\n                    row.append(str(len(vals)))\n                elif s == \"mean\":\n                    row.append(str(sum(nums) / len(nums)) if nums and len(nums) == len(vals) else None)\n                elif s == \"stddev\":\n                    if nums and len(nums) == len(vals) and len(nums) > 1:\n                        mu = sum(nums) / len(nums)\n                        row.append(str((sum((x - mu) ** 2 for x in nums) / (len(nums) - 1)) ** 0.5))\n                    else:\n                        row.append(None)\n                elif s == \"min\":\n                    row.append(str(min(vals)) if vals else None)\n                else:\n                    row.append(str(max(vals)) if vals else None)\n            out.append(tuple(row))\n        return self._new([\"summary\"] + cols, out)\n\n    summary = describe\n\n    def show(self, n=20, truncate=True, vertical=False):\n        print(self._show_string(n, truncate, vertical))\n\n    def _show_string(self, n=20, truncate=True, vertical=False):\n        names = self.columns\n        rows = self._rows[:n]\n        tl = 20 if truncate is True else (truncate if isinstance(truncate, int) and truncate > 1 else 10 ** 9)\n\n        def fmt(v):\n            s = _fmt_value(v)\n            if len(s) > tl:\n                s = s[:tl - 3] + \"...\"\n            return s\n        cells = [[fmt(v) for v in r] for r in rows]\n        if vertical:\n            lines = []\n            w = max([len(x) for x in names] + [0])\n            for k, r in enumerate(cells):\n                lines.append(\"-RECORD %d\" % k + \"-\" * 20)\n                for name, v in zip(names, r):\n                    lines.append(\" %s | %s\" % (name.ljust(w), v))\n            return \"\\n\".join(lines) if lines else \"(0 filas)\"\n        widths = [max([len(h)] + [len(r[i]) for r in cells] + [3]) for i, h in enumerate(names)]\n        sep = \"+\" + \"+\".join(\"-\" * w for w in widths) + \"+\"\n        out = [sep, \"|\" + \"|\".join(h.rjust(w) for h, w in zip(names, widths)) + \"|\", sep]\n        for r in cells:\n            out.append(\"|\" + \"|\".join(v.rjust(w) for v, w in zip(r, widths)) + \"|\")\n        out.append(sep)\n        if len(self._rows) > n:\n            out.append(\"only showing top %d row%s\" % (n, \"s\" if n != 1 else \"\"))\n        return \"\\n\".join(out)\n\n    def __repr__(self):\n        return \"DataFrame[%s]\" % \", \".join(\"%s: %s\" % d for d in self.dtypes)\n\n    # ---- compatibilidad\n    def transform(self, func, *args, **kwargs):\n        return func(self, *args, **kwargs)\n\n    def to(self, schema):\n        return self.select(*[F_col(f.name).cast(f.dataType) for f in schema.fields])\n\n    def unpivot(self, ids, values, variableColumnName, valueColumnName):\n        ids = [ids] if isinstance(ids, str) else list(ids)\n        values = [values] if isinstance(values, str) else list(values)\n        ii = [self._resolve(c) for c in ids]\n        vi = [self._resolve(c) for c in values]\n        rows = []\n        for r in self._rows:\n            for name, k in zip(values, vi):\n                rows.append(tuple(r[i] for i in ii) + (name, r[k]))\n        return self._new(ids + [variableColumnName, valueColumnName], rows)\n\n    melt = unpivot\n\n\ndef F_col(name):\n    return _col(name)\n\n\ndef _only_in_window(c):\n    \"\"\"True si todas las agregaciones de la expresión están dentro de una ventana.\"\"\"\n    if c.kind == \"win\":\n        return True\n    if c.kind == \"agg\":\n        return False\n    return all(_only_in_window(ch) for ch in c.children if isinstance(ch, Column)) and \\\n        all(_only_in_window(_as_col(v)) and _only_in_window(cnd) for cnd, v in c.kw.get(\"branches\", []))\n\n\ndef _equi_keys(cond, left, right):\n    \"\"\"Detecta condiciones col_izq == col_der (posiblemente con AND) para usar hash join.\"\"\"\n    lk, rk = [], []\n\n    def belongs(col, df):\n        if col.kind != \"ref\":\n            return False\n        try:\n            df._resolve(col._name, col.kw.get(\"df_id\"))\n            return True\n        except AnalysisException:\n            return False\n\n    def walk(c):\n        op = c.kw.get(\"op\") if c.kind == \"fn\" else None\n        if op == \"and\":\n            return walk(c.children[0]) and walk(c.children[1])\n        if op == \"=\" and c.children[0].kind == \"ref\" and c.children[1].kind == \"ref\":\n            a, b = c.children\n            if belongs(a, left) and belongs(b, right):\n                lk.append(a)\n                rk.append(b)\n                return True\n            if belongs(b, left) and belongs(a, right):\n                lk.append(b)\n                rk.append(a)\n                return True\n        return False\n\n    try:\n        ok = walk(cond)\n    except Exception:\n        return None\n    return (lk, rk) if ok and lk else None\n\n\ndef _fmt_value(v):\n    if v is None:\n        return \"NULL\"\n    if isinstance(v, bool):\n        return \"true\" if v else \"false\"\n    if isinstance(v, float):\n        if v != v:\n            return \"NaN\"\n        r = repr(v)\n        if \"e\" in r:\n            return r\n        return r\n    if isinstance(v, (list, tuple)):\n        return \"[\" + \", \".join(_fmt_value(x) for x in v) + \"]\"\n    if isinstance(v, dict):\n        return \"{\" + \", \".join(\"%s -> %s\" % (_fmt_value(k), _fmt_value(x)) for k, x in v.items()) + \"}\"\n    if isinstance(v, Row):\n        return \"{\" + \", \".join(_fmt_value(x) for x in v) + \"}\"\n    return str(v)\n\n\ndef _jsonable(v):\n    if isinstance(v, (_dt.date, _dt.datetime)):\n        return v.isoformat(sep=\" \") if isinstance(v, _dt.datetime) else v.isoformat()\n    return v\n\n\n# ---------------------------------------------------------------------- GroupedData\nclass GroupedData:\n    def __init__(self, df, keys, mode=\"group\"):\n        self._df = df\n        self._keys = keys\n        self._mode = mode\n        self._pivot = None\n\n    def _key_names(self):\n        names = []\n        for k in self._keys:\n            names.append(k.kw.get(\"alias\") or (k._name.split(\".\")[-1] if k.kind == \"ref\" else k._out_name()))\n        return names\n\n    def _groups(self):\n        df = self._df\n        vecs = [df._eval_col(k) for k in self._keys]\n        groups = {}\n        order = []\n        for i in range(len(df._rows)):\n            key = tuple(_hashable(v[i]) for v in vecs)\n            if key not in groups:\n                groups[key] = []\n                order.append(key)\n            groups[key].append(i)\n        if not self._keys and not groups:\n            groups[()] = []\n            order.append(())\n        return order, groups\n\n    def agg(self, *exprs):\n        if len(exprs) == 1 and isinstance(exprs[0], dict):\n            from . import functions as F\n            exprs = [getattr(F, fn if fn != \"mean\" else \"avg\")(c).alias(\"%s(%s)\" % (fn, c)) for c, fn in exprs[0].items()]\n        exprs = [e for e in exprs]\n        for e in exprs:\n            if not isinstance(e, Column):\n                raise TypeError(\"agg espera expresiones como F.sum('col'), no %r\" % (e,))\n        df = self._df\n        names = self._key_names() + [e._out_name() for e in exprs]\n        if self._mode in (\"rollup\", \"cube\"):\n            return self._rollup(exprs, names)\n        order, groups = self._groups()\n        if self._pivot:\n            return self._do_pivot(exprs, order, groups)\n        rows = []\n        for key in order:\n            sub = df._new(df._fields, [df._rows[i] for i in groups[key]], df._types)\n            sub._id = df._id\n            rows.append(tuple(key) + tuple(e._eval_group(sub) for e in exprs))\n        out = df._new(names, rows)\n        return out\n\n    def _rollup(self, exprs, names):\n        import itertools\n        df = self._df\n        nk = len(self._keys)\n        vecs = [df._eval_col(k) for k in self._keys]\n        if self._mode == \"rollup\":\n            sets = [tuple(range(i)) for i in range(nk, -1, -1)]\n        else:\n            sets = []\n            for r in range(nk, -1, -1):\n                sets.extend(itertools.combinations(range(nk), r))\n        rows = []\n        for s in sets:\n            groups, order = {}, []\n            for i in range(len(df._rows)):\n                key = tuple(_hashable(vecs[k][i]) if k in s else None for k in range(nk))\n                if key not in groups:\n                    groups[key] = []\n                    order.append(key)\n                groups[key].append(i)\n            for key in order:\n                sub = df._new(df._fields, [df._rows[i] for i in groups[key]], df._types)\n                rows.append(key + tuple(e._eval_group(sub) for e in exprs))\n        return df._new(names, rows)\n\n    def pivot(self, col, values=None):\n        self._pivot = (col, values)\n        return self\n\n    def _do_pivot(self, exprs, order, groups):\n        df = self._df\n        col, values = self._pivot\n        pv = _col(col)._eval(df)\n        if values is None:\n            values = sorted(set(v for v in pv if v is not None), key=lambda x: (str(type(x)), x))\n        names = self._key_names()\n        for v in values:\n            for e in exprs:\n                names.append(str(v) if len(exprs) == 1 else \"%s_%s\" % (v, e._out_name()))\n        rows = []\n        for key in order:\n            idxs = groups[key]\n            row = list(key)\n            for v in values:\n                sub_rows = [df._rows[i] for i in idxs if pv[i] == v]\n                sub = df._new(df._fields, sub_rows, df._types)\n                for e in exprs:\n                    row.append(e._eval_group(sub) if sub_rows else None)\n            rows.append(tuple(row))\n        return df._new(names, rows)\n\n    def count(self):\n        from . import functions as F\n        return self.agg(F.count(F.lit(1)).alias(\"count\"))\n\n    def _simple(self, fn, cols):\n        from . import functions as F\n        if not cols:\n            cols = [f for i, f in enumerate(self._df.columns) if isinstance(next((r[i] for r in self._df._rows if r[i] is not None), None), (int, float))]\n        return self.agg(*[getattr(F, fn)(c).alias(\"%s(%s)\" % (fn, c)) for c in cols])\n\n    def sum(self, *cols): return self._simple(\"sum\", cols)\n    def avg(self, *cols): return self._simple(\"avg\", cols)\n    mean = avg\n    def max(self, *cols): return self._simple(\"max\", cols)\n    def min(self, *cols): return self._simple(\"min\", cols)\n\n    def applyInPandas(self, *a, **k):\n        raise NotImplementedError(\"applyInPandas no está disponible en el simulador\")\n\n\n# ----------------------------------------------------------------------- NA helpers\nclass _NA:\n    def __init__(self, df):\n        self.df = df\n\n    def fill(self, value, subset=None):\n        df = self.df\n        if isinstance(subset, str):\n            subset = [subset]\n        if isinstance(value, dict):\n            mapping = value\n        else:\n            names = subset or df.columns\n            mapping = {}\n            for i, c in enumerate(df.columns):\n                if c not in names:\n                    continue\n                sample = next((r[i] for r in df._rows if r[i] is not None), None)\n                if isinstance(value, bool):\n                    if isinstance(sample, bool) or sample is None:\n                        mapping[c] = value\n                elif isinstance(value, (int, float)):\n                    if isinstance(sample, (int, float)) and not isinstance(sample, bool):\n                        mapping[c] = value\n                    elif sample is None and subset:\n                        mapping[c] = value\n                elif isinstance(value, str):\n                    if isinstance(sample, str) or (sample is None and subset):\n                        mapping[c] = value\n        idx = {df.columns.index(k): v for k, v in mapping.items() if k in df.columns}\n        rows = [tuple(idx[i] if (i in idx and v is None) else v for i, v in enumerate(r)) for r in df._rows]\n        return df._new(df._fields, rows, df._types)\n\n    def drop(self, how=\"any\", thresh=None, subset=None):\n        df = self.df\n        if isinstance(subset, str):\n            subset = [subset]\n        idx = [df.columns.index(c) for c in (subset or df.columns)]\n        rows = []\n        for r in df._rows:\n            nn = sum(1 for i in idx if r[i] is not None)\n            if thresh is not None:\n                ok = nn >= thresh\n            elif how == \"all\":\n                ok = nn > 0\n            else:\n                ok = nn == len(idx)\n            if ok:\n                rows.append(r)\n        return df._new(df._fields, rows, df._types)\n\n    def replace(self, to_replace, value=None, subset=None):\n        df = self.df\n        if isinstance(to_replace, dict):\n            mapping = to_replace\n        elif isinstance(to_replace, (list, tuple)):\n            vals = value if isinstance(value, (list, tuple)) else [value] * len(to_replace)\n            mapping = dict(zip(to_replace, vals))\n        else:\n            mapping = {to_replace: value}\n        if isinstance(subset, str):\n            subset = [subset]\n        idx = set(df.columns.index(c) for c in (subset or df.columns))\n        rows = [tuple(mapping.get(v, v) if (i in idx and not isinstance(v, (list, dict)) and v in mapping) else v\n                      for i, v in enumerate(r)) for r in df._rows]\n        return df._new(df._fields, rows, df._types)\n\n\n# ---------------------------------------------------------------------------- RDD\nclass _RDDList(list):\n    def collect(self):\n        return list(self)\n\n    def take(self, n):\n        return list(self[:n])\n\n\nclass _RDD:\n    def __init__(self, df):\n        self.df = df\n\n    def getNumPartitions(self):\n        return self.df._partitions\n\n    def collect(self):\n        return self.df.collect()\n\n    def map(self, f):\n        return _PyRDD([f(r) for r in self.df.collect()])\n\n    def flatMap(self, f):\n        return _PyRDD([x for r in self.df.collect() for x in f(r)])\n\n    def filter(self, f):\n        return _PyRDD([r for r in self.df.collect() if f(r)])\n\n    def count(self):\n        return self.df.count()\n\n    def toDF(self, schema=None):\n        return self.df\n\n\nclass _PyRDD:\n    \"\"\"RDD mínimo en memoria para practicar map/filter/reduceByKey.\"\"\"\n\n    def __init__(self, data, n=8):\n        self._data = list(data)\n        self._n = n\n\n    def map(self, f): return _PyRDD([f(x) for x in self._data], self._n)\n    def flatMap(self, f): return _PyRDD([y for x in self._data for y in f(x)], self._n)\n    def filter(self, f): return _PyRDD([x for x in self._data if f(x)], self._n)\n    def distinct(self): return _PyRDD(list(dict.fromkeys(self._data)), self._n)\n    def collect(self): return list(self._data)\n    def count(self): return len(self._data)\n    def take(self, n): return self._data[:n]\n    def first(self): return self._data[0]\n    def sum(self): return sum(self._data)\n    def max(self): return max(self._data)\n    def min(self): return min(self._data)\n    def mean(self): return sum(self._data) / len(self._data)\n    def getNumPartitions(self): return self._n\n    def repartition(self, n): return _PyRDD(self._data, n)\n    def coalesce(self, n): return _PyRDD(self._data, min(n, self._n))\n    def cache(self): return self\n    def persist(self, *a): return self\n    def keys(self): return _PyRDD([k for k, _ in self._data], self._n)\n    def values(self): return _PyRDD([v for _, v in self._data], self._n)\n    def mapValues(self, f): return _PyRDD([(k, f(v)) for k, v in self._data], self._n)\n    def countByValue(self):\n        out = {}\n        for x in self._data:\n            out[x] = out.get(x, 0) + 1\n        return out\n\n    def countByKey(self):\n        out = {}\n        for k, _ in self._data:\n            out[k] = out.get(k, 0) + 1\n        return out\n\n    def reduce(self, f):\n        import functools\n        return functools.reduce(f, self._data)\n\n    def fold(self, zero, f):\n        import functools\n        return functools.reduce(f, self._data, zero)\n\n    def reduceByKey(self, f):\n        out = {}\n        for k, v in self._data:\n            out[k] = f(out[k], v) if k in out else v\n        return _PyRDD(list(out.items()), self._n)\n\n    def groupByKey(self):\n        out = {}\n        for k, v in self._data:\n            out.setdefault(k, []).append(v)\n        return _PyRDD(list(out.items()), self._n)\n\n    def sortBy(self, f, ascending=True):\n        return _PyRDD(sorted(self._data, key=f, reverse=not ascending), self._n)\n\n    def sortByKey(self, ascending=True):\n        return _PyRDD(sorted(self._data, key=lambda kv: kv[0], reverse=not ascending), self._n)\n\n    def join(self, other):\n        idx = {}\n        for k, v in other._data:\n            idx.setdefault(k, []).append(v)\n        return _PyRDD([(k, (v, w)) for k, v in self._data for w in idx.get(k, [])], self._n)\n\n    def union(self, other):\n        return _PyRDD(self._data + other._data, self._n + other._n)\n\n    def zipWithIndex(self):\n        return _PyRDD([(x, i) for i, x in enumerate(self._data)], self._n)\n\n    def glom(self):\n        n = self._n\n        size = max(1, -(-len(self._data) // n))\n        return _PyRDD([self._data[i:i + size] for i in range(0, len(self._data), size)], n)\n\n    def toDF(self, schema=None):\n        return SparkSession._active.createDataFrame(self._data, schema)\n\n\nclass _SparkContext:\n    def __init__(self, session):\n        self.session = session\n        self.appName = session._app\n        self.master = \"local[*]\"\n        self.defaultParallelism = 8\n        self.version = SparkSession.version\n\n    def parallelize(self, data, numSlices=None):\n        return _PyRDD(data, numSlices or 8)\n\n    def textFile(self, path, *a):\n        if path in _FILES and isinstance(_FILES[path], str):\n            return _PyRDD(_FILES[path].splitlines())\n        raise AnalysisException(\"Ruta no encontrada en el sistema de archivos simulado: %s\" % path)\n\n    def setLogLevel(self, level):\n        pass\n\n    def broadcast(self, value):\n        class _B:\n            def __init__(self, v):\n                self.value = v\n        return _B(value)\n\n    def accumulator(self, value):\n        class _A:\n            def __init__(self, v):\n                self.value = v\n\n            def add(self, x):\n                self.value += x\n\n            def __iadd__(self, x):\n                self.value += x\n                return self\n        return _A(value)\n\n\n# ------------------------------------------------------------------- reader/writer\nclass DataFrameReader:\n    def __init__(self, session):\n        self._s = session\n        self._fmt = \"parquet\"\n        self._opts = {}\n        self._schema = None\n\n    def format(self, f):\n        self._fmt = f\n        return self\n\n    def option(self, k, v):\n        self._opts[k] = v\n        return self\n\n    def options(self, **kw):\n        self._opts.update(kw)\n        return self\n\n    def schema(self, s):\n        self._schema = s\n        return self\n\n    def load(self, path=None):\n        if path is None:\n            raise AnalysisException(\"load() necesita una ruta\")\n        return self._read(path)\n\n    def _read(self, path):\n        p = path.rstrip(\"/\")\n        df = _FILES.get(p)\n        if df is None:\n            base = p.split(\"/\")[-1]\n            name = base.split(\".\")[0]\n            if _lazy_get(name.lower()) is not None:\n                df = _lazy_get(name.lower())\n        if df is None:\n            raise AnalysisException(\"[PATH_NOT_FOUND] La ruta no existe: %s. Rutas disponibles: %s\"\n                                    % (path, sorted(set(list(_FILES.keys()) + [\"/datos/%s.csv\" % k for k in _all_table_names()]))))\n        if isinstance(df, str):\n            return self._parse_csv_text(df)\n        if self._fmt == \"csv\" and not _truthy(self._opts.get(\"inferSchema\")) and self._schema is None:\n            # como Spark: sin inferSchema todas las columnas son string\n            out = df.select(*[F_col(c).cast(\"string\").alias(c) for c in df.columns])\n        else:\n            out = df._new(df._fields, df._rows, df._types)\n        if self._fmt == \"csv\" and not _truthy(self._opts.get(\"header\")) and self._schema is None:\n            out = out.toDF(*[\"_c%d\" % i for i in range(len(out.columns))])\n        if self._schema is not None:\n            from . import types as T\n            sch = T._parse_schema(self._schema) if isinstance(self._schema, str) else self._schema\n            out = out.select(*[F_col(c).cast(f.dataType).alias(f.name) for c, f in zip(out.columns, sch.fields)])\n        return out\n\n    def _parse_csv_text(self, text):\n        import csv\n        import io\n        sep = self._opts.get(\"sep\", self._opts.get(\"delimiter\", \",\"))\n        reader = list(csv.reader(io.StringIO(text), delimiter=sep))\n        header = _truthy(self._opts.get(\"header\"))\n        names = reader[0] if header else [\"_c%d\" % i for i in range(len(reader[0]))]\n        data = reader[1:] if header else reader\n        rows = [tuple(v if v != \"\" else None for v in r) for r in data]\n        df = self._s.createDataFrame(rows, names)\n        if _truthy(self._opts.get(\"inferSchema\")):\n            from . import types as T\n            casts = []\n            for i, c in enumerate(names):\n                vals = [r[i] for r in rows if r[i] is not None]\n                t = \"string\"\n                if vals and all(_re.fullmatch(r\"-?\\d+\", v) for v in vals):\n                    t = \"int\"\n                elif vals and all(_re.fullmatch(r\"-?\\d+(\\.\\d+)?\", v) for v in vals):\n                    t = \"double\"\n                casts.append(F_col(c).cast(t).alias(c))\n            df = df.select(*casts)\n        return df\n\n    def csv(self, path, header=None, inferSchema=None, sep=None, schema=None):\n        self._fmt = \"csv\"\n        if header is not None:\n            self._opts[\"header\"] = header\n        if inferSchema is not None:\n            self._opts[\"inferSchema\"] = inferSchema\n        if sep is not None:\n            self._opts[\"sep\"] = sep\n        if schema is not None:\n            self._schema = schema\n        return self._read(path)\n\n    def parquet(self, path):\n        self._fmt = \"parquet\"\n        return self._read(path)\n\n    def json(self, path, **kw):\n        self._fmt = \"json\"\n        return self._read(path)\n\n    def table(self, name):\n        return self._s.table(name)\n\n\ndef _truthy(v):\n    return v is True or (isinstance(v, str) and v.lower() == \"true\")\n\n\nclass DataFrameWriter:\n    def __init__(self, df):\n        self._df = df\n        self._mode = \"errorifexists\"\n        self._fmt = \"parquet\"\n        self._parts = []\n        self._opts = {}\n\n    def mode(self, m):\n        self._mode = m.lower()\n        return self\n\n    def format(self, f):\n        self._fmt = f\n        return self\n\n    def option(self, k, v):\n        self._opts[k] = v\n        return self\n\n    def options(self, **kw):\n        self._opts.update(kw)\n        return self\n\n    def partitionBy(self, *cols):\n        self._parts = list(cols)\n        return self\n\n    def bucketBy(self, n, *cols):\n        return self\n\n    def sortBy(self, *cols):\n        return self\n\n    def _store(self, store, key, label):\n        exists = key in store\n        if exists and self._mode in (\"error\", \"errorifexists\"):\n            raise AnalysisException(\"[%s_ALREADY_EXISTS] %s ya existe. Usa .mode('overwrite') o .mode('append').\" % (label, key))\n        if exists and self._mode == \"ignore\":\n            return\n        if exists and self._mode == \"append\":\n            old = store[key]\n            store[key] = old.unionByName(self._df)\n        else:\n            store[key] = self._df._new(self._df._fields, self._df._rows, self._df._types)\n        msg = \"✔ Escritos %d registros en %s (formato %s, modo %s\" % (self._df.count(), key, self._fmt, self._mode)\n        if self._parts:\n            msg += \", particionado por %s\" % \", \".join(self._parts)\n        print(msg + \")\")\n\n    def save(self, path=None):\n        self._store(_FILES, path.rstrip(\"/\"), \"PATH\")\n\n    def parquet(self, path, mode=None, partitionBy=None):\n        if mode:\n            self._mode = mode\n        if partitionBy:\n            self._parts = [partitionBy] if isinstance(partitionBy, str) else partitionBy\n        self._fmt = \"parquet\"\n        self.save(path)\n\n    def csv(self, path, mode=None, header=None):\n        if mode:\n            self._mode = mode\n        self._fmt = \"csv\"\n        self.save(path)\n\n    def json(self, path, mode=None):\n        if mode:\n            self._mode = mode\n        self._fmt = \"json\"\n        self.save(path)\n\n    def saveAsTable(self, name):\n        self._store(_CATALOG, name.lower(), \"TABLE_OR_VIEW\")\n\n    def insertInto(self, name, overwrite=False):\n        self._mode = \"overwrite\" if overwrite else \"append\"\n        self._store(_CATALOG, name.lower(), \"TABLE_OR_VIEW\")\n\n\n# --------------------------------------------------------------------- SparkSession\nclass _Builder:\n    def __init__(self):\n        self._app = \"mini-spark\"\n        self._conf = {}\n\n    def appName(self, n):\n        self._app = n\n        return self\n\n    def master(self, m):\n        return self\n\n    def config(self, k=None, v=None, **kw):\n        if k:\n            self._conf[k] = v\n        return self\n\n    def enableHiveSupport(self):\n        return self\n\n    def getOrCreate(self):\n        if SparkSession._active is None:\n            SparkSession._active = SparkSession(self._app)\n        SparkSession._active.conf._d.update(self._conf)\n        return SparkSession._active\n\n\nclass _Conf:\n    def __init__(self):\n        self._d = {\"spark.sql.shuffle.partitions\": \"200\", \"spark.sql.adaptive.enabled\": \"true\",\n                   \"spark.sql.autoBroadcastJoinThreshold\": \"10485760\"}\n\n    def set(self, k, v):\n        self._d[k] = str(v)\n\n    def get(self, k, default=None):\n        return self._d.get(k, default)\n\n\nclass _Catalog:\n    def listTables(self, db=None):\n        return [_mkrow([\"name\", \"isTemporary\"], (k, False)) for k in sorted(_all_table_names())] + \\\n               [_mkrow([\"name\", \"isTemporary\"], (k, True)) for k in sorted(_TEMP_VIEWS)]\n\n    def tableExists(self, name, db=None):\n        return name.lower() in _all_table_names() or name.lower() in _TEMP_VIEWS\n\n    def dropTempView(self, name):\n        return _TEMP_VIEWS.pop(name.lower(), None) is not None\n\n    def cacheTable(self, name):\n        pass\n\n    def clearCache(self):\n        pass\n\n    def currentDatabase(self):\n        return \"default\"\n\n\nclass SparkSession:\n    _active = None\n    version = \"4.2.1 (mini-Spark simulado)\"\n\n    class _BuilderDesc:\n        def __get__(self, obj, cls):\n            return _Builder()\n\n    builder = _BuilderDesc()\n\n    def __init__(self, app=\"mini-spark\"):\n        self._app = app\n        self.conf = _Conf()\n        self.catalog = _Catalog()\n        self.sparkContext = _SparkContext(self)\n\n    @classmethod\n    def getActiveSession(cls):\n        return cls._active\n\n    @property\n    def read(self):\n        return DataFrameReader(self)\n\n    def stop(self):\n        pass\n\n    def newSession(self):\n        return self\n\n    def range(self, start, end=None, step=1, numPartitions=None):\n        if end is None:\n            start, end = 0, start\n        return DataFrame([\"id\"], [(i,) for i in range(start, end, step)], self)\n\n    def createDataFrame(self, data, schema=None, samplingRatio=None, verifySchema=True):\n        from . import types as T\n        if hasattr(data, \"to_dict\") and hasattr(data, \"columns\"):  # pandas\n            cols = [str(c) for c in data.columns]\n            rows = [tuple(None if (isinstance(v, float) and v != v) else v for v in r) for r in data.itertuples(index=False)]\n            return DataFrame(cols, rows, self)\n        if isinstance(data, _PyRDD):\n            data = data.collect()\n        data = list(data)\n        types = None\n        if isinstance(schema, str):\n            if \":\" in schema or \" \" in schema.strip() or \",\" in schema:\n                schema = T._parse_schema(schema)\n            else:\n                schema = [schema]\n        if isinstance(schema, (T.DataType,)) and not isinstance(schema, T.StructType):\n            schema = T.StructType([T.StructField(\"value\", schema)])\n            data = [(x,) for x in data]\n        if isinstance(schema, T.StructType):\n            names = [f.name for f in schema.fields]\n            types = [f.dataType for f in schema.fields]\n        elif isinstance(schema, (list, tuple)):\n            names = list(schema)\n        else:\n            names = None\n        rows = []\n        for r in data:\n            if isinstance(r, Row) and r.__fields__:\n                if names is None:\n                    names = list(r.__fields__)\n                rows.append(tuple(r[n] for n in names) if set(names) <= set(r.__fields__) else tuple(r))\n            elif isinstance(r, dict):\n                if names is None:\n                    names = list(r.keys())\n                rows.append(tuple(r.get(n) for n in names))\n            elif isinstance(r, (list, tuple)):\n                rows.append(tuple(r))\n            else:\n                rows.append((r,))\n        if names is None:\n            names = [\"_%d\" % (i + 1) for i in range(len(rows[0]) if rows else 0)]\n        if rows and len(rows[0]) != len(names):\n            raise AnalysisException(\"El esquema tiene %d columnas pero los datos tienen %d\" % (len(names), len(rows[0])))\n        if types:\n            for k, t in enumerate(types):\n                for r in rows:\n                    v = r[k]\n                    if v is None:\n                        if verifySchema and isinstance(schema, T.StructType) and not schema.fields[k].nullable:\n                            raise AnalysisException(\"El campo '%s' no admite NULL\" % names[k])\n                        continue\n                    if isinstance(t, (T.IntegerType, T.LongType)) and not isinstance(v, int):\n                        raise TypeError(\"El campo %s: %s no acepta el valor %r de tipo %s\" % (names[k], t.simpleString(), v, type(v).__name__))\n                    if isinstance(t, T.StringType) and not isinstance(v, str):\n                        raise TypeError(\"El campo %s: string no acepta el valor %r de tipo %s\" % (names[k], v, type(v).__name__))\n        return DataFrame(names, rows, self, types)\n\n    def table(self, name):\n        key = name.lower()\n        if key.startswith(\"default.\"):\n            key = key[8:]\n        if key in _TEMP_VIEWS:\n            return _TEMP_VIEWS[key]\n        df = _lazy_get(key)\n        if df is not None:\n            return df._new(df._fields, df._rows, df._types)\n        raise AnalysisException(\"[TABLE_OR_VIEW_NOT_FOUND] La tabla o vista '%s' no existe. Disponibles: %s\"\n                                % (name, sorted(_all_table_names() | set(_TEMP_VIEWS))))\n\n    # ---- SQL vía sqlite3\n    def sql(self, query, **kwargs):\n        if kwargs:\n            query = query.format(**kwargs)\n        q = query.strip().rstrip(\";\")\n        m = _re.match(r\"(?is)^create\\s+(or\\s+replace\\s+)?(temp(orary)?\\s+)?(view|table)\\s+(if\\s+not\\s+exists\\s+)?([\\w.]+)\\s+as\\s+(.*)$\", q)\n        if m:\n            name, body = m.group(6), m.group(7)\n            df = self.sql(body)\n            if m.group(4).lower() == \"view\":\n                df.createOrReplaceTempView(name)\n            else:\n                _CATALOG[name.lower()] = df\n            return DataFrame([], [], self)\n        m = _re.match(r\"(?is)^(show\\s+tables)$\", q)\n        if m:\n            return self.createDataFrame([(k, k in _TEMP_VIEWS) for k in sorted(_all_table_names() | set(_TEMP_VIEWS))], [\"tableName\", \"isTemporary\"])\n        m = _re.match(r\"(?is)^(describe|desc)\\s+(table\\s+)?([\\w.]+)$\", q)\n        if m:\n            df = self.table(m.group(3))\n            return self.createDataFrame([(c, t, None) for c, t in df.dtypes], [\"col_name\", \"data_type\", \"comment\"])\n        return self._run_sql(q)\n\n    def _run_sql(self, q, extra=None):\n        conn = _sqlite3.connect(\":memory:\")\n        _register_functions(conn)\n        names = _all_table_names() | set(_TEMP_VIEWS) | set(extra or {})\n        # tablas referenciadas: cargamos solo las que aparecen en la consulta\n        ql = q.lower()\n        for name in names:\n            nm = name.replace(\"global_temp.\", \"\")\n            if _re.search(r\"\\b%s\\b\" % _re.escape(nm), ql):\n                df = (extra or {}).get(name) or _TEMP_VIEWS.get(name) or _lazy_get(name)\n                if df is not None:\n                    _load_sqlite(conn, nm, df)\n        q2 = _translate_sql(q)\n        try:\n            cur = conn.execute(q2)\n        except _sqlite3.Error as e:\n            msg = str(e)\n            if \"no such table\" in msg:\n                msg += \". ¿Registraste la vista con df.createOrReplaceTempView('nombre')?\"\n            raise AnalysisException(\"[SQL] \" + msg)\n        names = [d[0] for d in cur.description] if cur.description else []\n        rows = cur.fetchall()\n        conn.close()\n        return DataFrame(names, rows, self)\n\n    def _sql_on(self, df, q, keep_types=False):\n        out = self._run_sql(q, {\"__t\": df})\n        if keep_types and out.columns == df.columns:\n            out._types = df._types\n            out._rows = [tuple(_restore(v, t) for v, t in zip(r, [df._col_type(i) for i in range(len(df._fields))])) for r in out._rows]\n        return out\n\n\n\ndef _restore(v, t):\n    from . import types as T\n    if v is None:\n        return None\n    if isinstance(t, T.DateType) and isinstance(v, str):\n        return _to_date(v)\n    if isinstance(t, T.TimestampType) and isinstance(v, str):\n        return _to_ts(v)\n    if isinstance(t, T.BooleanType) and isinstance(v, int):\n        return bool(v)\n    return v\n\n\ndef _load_sqlite(conn, name, df):\n    cols = \", \".join('\"%s\"' % c for c in df.columns)\n    conn.execute('CREATE TABLE \"%s\" (%s)' % (name, cols))\n    ph = \", \".join(\"?\" * len(df.columns))\n\n    def conv(v):\n        if isinstance(v, (_dt.date, _dt.datetime)):\n            return v.isoformat(sep=\" \") if isinstance(v, _dt.datetime) else v.isoformat()\n        if isinstance(v, (list, dict, tuple)):\n            return str(v)\n        return v\n    conn.executemany('INSERT INTO \"%s\" VALUES (%s)' % (name, ph), [tuple(conv(v) for v in r) for r in df._rows])\n\n\ndef _translate_sql(q):\n    \"\"\"Traduce algunas funciones de Spark SQL a SQLite.\"\"\"\n    rep = [\n        (r\"(?i)\\byear\\s*\\(\", \"_year(\"), (r\"(?i)\\bmonth\\s*\\(\", \"_month(\"), (r\"(?i)\\bday(ofmonth)?\\s*\\(\", \"_day(\"),\n        (r\"(?i)\\bdate_format\\s*\\(\", \"_date_format(\"), (r\"(?i)\\bdatediff\\s*\\(\", \"_datediff(\"),\n        (r\"(?i)\\bdate_add\\s*\\(\", \"_date_add(\"), (r\"(?i)\\bdate_sub\\s*\\(\", \"_date_sub(\"),\n        (r\"(?i)\\bto_date\\s*\\(\", \"date(\"), (r\"(?i)\\bcurrent_date\\s*\\(\\s*\\)\", \"date('now')\"),\n        (r\"(?i)\\bnvl\\s*\\(\", \"ifnull(\"), (r\"(?i)\\bconcat\\s*\\(\", \"_concat(\"), (r\"(?i)\\bsize\\s*\\(\", \"_size(\"),\n        (r\"(?i)\\bdate_trunc\\s*\\(\", \"_date_trunc(\"), (r\"(?i)\\bint\\s*\\(\", \"_int(\"),\n        (r\"(?i)\\blast_day\\s*\\(\", \"_last_day(\"), (r\"(?i)\\btrunc\\s*\\(\", \"_date_trunc_r(\"),\n        (r\"(?i)\\bRLIKE\\b\", \"REGEXP\"),\n    ]\n    for a, b in rep:\n        q = _re.sub(a, b, q)\n    return q\n\n\ndef _register_functions(conn):\n    def d(v):\n        return _to_date(v)\n    conn.create_function(\"_year\", 1, lambda v: d(v).year if d(v) else None)\n    conn.create_function(\"_month\", 1, lambda v: d(v).month if d(v) else None)\n    conn.create_function(\"_day\", 1, lambda v: d(v).day if d(v) else None)\n    conn.create_function(\"_date_format\", 2, lambda v, f: (_to_ts(v).strftime(_java_fmt(f)) if _to_ts(v) else None))\n    conn.create_function(\"_datediff\", 2, lambda a, b: (d(a) - d(b)).days if d(a) and d(b) else None)\n    conn.create_function(\"_date_add\", 2, lambda a, n: (d(a) + _dt.timedelta(days=n)).isoformat() if d(a) else None)\n    conn.create_function(\"_date_sub\", 2, lambda a, n: (d(a) - _dt.timedelta(days=n)).isoformat() if d(a) else None)\n    conn.create_function(\"_concat\", -1, lambda *a: None if any(x is None for x in a) else \"\".join(str(x) for x in a))\n    conn.create_function(\"_size\", 1, lambda v: None if v is None else len(str(v).split(\",\")))\n    conn.create_function(\"_int\", 1, lambda v: None if v is None else int(float(v)))\n    conn.create_function(\"_date_trunc\", 2, lambda unit, v: _trunc(v, unit))\n    conn.create_function(\"_date_trunc_r\", 2, lambda v, unit: _trunc(v, unit, as_date=True))\n    conn.create_function(\"_last_day\", 1, lambda v: _last_day(d(v)).isoformat() if d(v) else None)\n    conn.create_function(\"REGEXP\", 2, lambda pat, s: None if s is None else 1 if _re.search(pat, str(s)) else 0)\n    conn.create_function(\"initcap\", 1, lambda s: None if s is None else str(s).title())\n    conn.create_function(\"sqrt\", 1, lambda x: None if x is None else x ** 0.5)\n    conn.create_function(\"power\", 2, lambda x, y: None if x is None or y is None else x ** y)\n    conn.create_function(\"pow\", 2, lambda x, y: None if x is None or y is None else x ** y)\n    conn.create_function(\"floor\", 1, lambda x: None if x is None else int(x // 1))\n    conn.create_function(\"ceil\", 1, lambda x: None if x is None else -int((-x) // 1))\n    conn.create_function(\"split_part\", 3, lambda s, sep, i: None if s is None else (str(s).split(sep) + [\"\"] * i)[i - 1])\n\n\ndef _last_day(dd):\n    import calendar\n    return dd.replace(day=calendar.monthrange(dd.year, dd.month)[1])\n\n\ndef _trunc(v, unit, as_date=False):\n    t = _to_ts(v)\n    if t is None:\n        return None\n    u = str(unit).lower()\n    if u in (\"year\", \"yyyy\", \"yy\"):\n        t = t.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)\n    elif u in (\"quarter\",):\n        t = t.replace(month=(t.month - 1) // 3 * 3 + 1, day=1, hour=0, minute=0, second=0, microsecond=0)\n    elif u in (\"month\", \"mon\", \"mm\"):\n        t = t.replace(day=1, hour=0, minute=0, second=0, microsecond=0)\n    elif u == \"week\":\n        t = (t - _dt.timedelta(days=t.weekday())).replace(hour=0, minute=0, second=0, microsecond=0)\n    elif u == \"day\" or u == \"dd\":\n        t = t.replace(hour=0, minute=0, second=0, microsecond=0)\n    elif u == \"hour\":\n        t = t.replace(minute=0, second=0, microsecond=0)\n    if as_date:\n        return t.date().isoformat()\n    return t.isoformat(sep=\" \")\n\n\nfrom . import functions  # noqa: E402\nfrom . import types  # noqa: E402\nfrom .window import Window, WindowSpec  # noqa: E402,F401\n\n\ndef _load_sample_tables(tables):\n    \"\"\"Carga las tablas de ejemplo (dict nombre -> {columns, rows}) en el catálogo.\n    Las columnas fecha_* se convierten a date/timestamp como haría Spark.\"\"\"\n    from . import types as T\n    out = {}\n    for name, t in tables.items():\n        cols = t[\"columns\"]\n        rows = [list(r) for r in t[\"rows\"]]\n        types = []\n        for i, c in enumerate(cols):\n            sample = next((r[i] for r in rows if r[i] is not None), None)\n            if c.startswith(\"fecha\") and isinstance(sample, str):\n                if len(sample) > 10:\n                    for r in rows:\n                        r[i] = _to_ts(r[i])\n                    types.append(T.TimestampType())\n                else:\n                    for r in rows:\n                        r[i] = _to_date(r[i])\n                    types.append(T.DateType())\n            elif isinstance(sample, float) or any(isinstance(r[i], float) for r in rows[:200]):\n                for r in rows:\n                    if r[i] is not None:\n                        r[i] = float(r[i])\n                types.append(T.DoubleType())\n            elif isinstance(sample, int):\n                types.append(T.IntegerType())\n            else:\n                types.append(T.StringType())\n        out[name] = DataFrame(cols, [tuple(r) for r in rows], None, types)\n    return out\n","pyspark/sql/functions.py":"\"\"\"Funciones de mini-Spark (imitan pyspark.sql.functions).\"\"\"\nimport builtins as _b\nimport datetime as _dt\nimport math as _math\nimport re as _re\n\nfrom . import Column, _as_col, _col, _lit, _cast, _to_date, _to_ts, _java_fmt, _hashable, AnalysisException, _last_day, _trunc\n\n_bsum, _bmin, _bmax, _babs, _bround = _b.sum, _b.min, _b.max, _b.abs, _b.round\n\n\ndef col(name):\n    return _col(name)\n\n\ncolumn = col\n\n\ndef lit(v):\n    if isinstance(v, Column):\n        return v\n    return _lit(v)\n\n\ndef expr(e):\n    \"\"\"Expresión SQL. Se evalúa con SQLite fila a fila (solo expresiones simples).\"\"\"\n    def run(df, children):\n        out = df.sparkSession._run_sql(\"SELECT %s AS __e FROM __t\" % e, {\"__t\": df})\n        return [r[0] for r in out._rows]\n    c = Column(\"fn\", e, [], run, rowwise_df=True)\n    return c\n\n\ndef _fn(name, cols, f):\n    cs = [_as_col(_col(c) if isinstance(c, str) else c) for c in cols]\n    return Column(\"fn\", \"%s(%s)\" % (name, \", \".join(c._name for c in cs)), cs, f)\n\n\ndef _null_safe(f):\n    def g(*a):\n        if any(x is None for x in a):\n            return None\n        return f(*a)\n    return g\n\n\ndef _c(x):\n    return _col(x) if isinstance(x, str) else _as_col(x)\n\n\n# ----------------------------------------------------------- agregaciones\ndef _agg(name, c, f):\n    cc = _c(c) if c is not None else None\n    label = \"%s(%s)\" % (name, cc._name if cc is not None else \"1\")\n    return Column(\"agg\", label, [cc] if cc is not None else [], f)\n\n\ndef _nn(vals):\n    return [v for v in vals if v is not None]\n\n\ndef sum(c):\n    def f(vals):\n        v = _nn(vals)\n        return _bsum(v) if v else None\n    return _agg(\"sum\", c, f)\n\n\ndef avg(c):\n    def f(vals):\n        v = _nn(vals)\n        return _bsum(v) / len(v) if v else None\n    return _agg(\"avg\", c, f)\n\n\nmean = avg\n\n\ndef count(c=\"*\"):\n    if isinstance(c, str) and c == \"*\":\n        return Column(\"agg\", \"count(1)\", [], lambda vals: len(vals))\n    cc = _c(c)\n    name = \"count(1)\" if cc.kind == \"lit\" else \"count(%s)\" % cc._name\n    return Column(\"agg\", name, [cc], lambda vals: len(_nn(vals)))\n\n\ndef countDistinct(c, *cols):\n    cs = [_c(c)] + [_c(x) for x in cols]\n    if len(cs) == 1:\n        return Column(\"agg\", \"count(DISTINCT %s)\" % cs[0]._name, cs, lambda vals: len(set(_hashable(v) for v in _nn(vals))))\n    tup = Column(\"fn\", \"struct\", cs, lambda *a: None if any(x is None for x in a) else tuple(a))\n    return Column(\"agg\", \"count(DISTINCT %s)\" % \", \".join(x._name for x in cs), [tup], lambda vals: len(set(_nn(vals))))\n\n\ncount_distinct = countDistinct\n\n\ndef approx_count_distinct(c, rsd=None):\n    a = countDistinct(c)\n    a._name = \"approx_count_distinct(%s)\" % _c(c)._name\n    return a\n\n\ndef sumDistinct(c):\n    return _agg(\"sum(DISTINCT)\", c, lambda vals: _bsum(set(_nn(vals))) if _nn(vals) else None)\n\n\nsum_distinct = sumDistinct\n\n\ndef max(c):\n    return _agg(\"max\", c, lambda vals: _bmax(_nn(vals)) if _nn(vals) else None)\n\n\ndef min(c):\n    return _agg(\"min\", c, lambda vals: _bmin(_nn(vals)) if _nn(vals) else None)\n\n\ndef max_by(c, ord_c):\n    tup = Column(\"fn\", \"pair\", [_c(c), _c(ord_c)], lambda a, b: (b, a))\n    return Column(\"agg\", \"max_by(%s, %s)\" % (_c(c)._name, _c(ord_c)._name), [tup],\n                  lambda vals: _bmax([v for v in vals if v[0] is not None], key=lambda t: t[0])[1] if vals else None)\n\n\ndef min_by(c, ord_c):\n    tup = Column(\"fn\", \"pair\", [_c(c), _c(ord_c)], lambda a, b: (b, a))\n    return Column(\"agg\", \"min_by(%s, %s)\" % (_c(c)._name, _c(ord_c)._name), [tup],\n                  lambda vals: _bmin([v for v in vals if v[0] is not None], key=lambda t: t[0])[1] if vals else None)\n\n\ndef first(c, ignorenulls=False):\n    def f(vals):\n        if ignorenulls:\n            v = _nn(vals)\n            return v[0] if v else None\n        return vals[0] if vals else None\n    return _agg(\"first\", c, f)\n\n\ndef last(c, ignorenulls=False):\n    def f(vals):\n        if ignorenulls:\n            v = _nn(vals)\n            return v[-1] if v else None\n        return vals[-1] if vals else None\n    return _agg(\"last\", c, f)\n\n\ndef collect_list(c):\n    return _agg(\"collect_list\", c, lambda vals: _nn(vals))\n\n\ndef collect_set(c):\n    def f(vals):\n        out = []\n        for v in _nn(vals):\n            if v not in out:\n                out.append(v)\n        return out\n    return _agg(\"collect_set\", c, f)\n\n\ndef _var(vals, sample=True):\n    v = _nn(vals)\n    n = len(v)\n    if n < (2 if sample else 1):\n        return None\n    mu = _bsum(v) / n\n    return _bsum((x - mu) ** 2 for x in v) / (n - 1 if sample else n)\n\n\ndef stddev(c):\n    return _agg(\"stddev\", c, lambda vals: None if _var(vals) is None else _var(vals) ** 0.5)\n\n\nstddev_samp = stddev\nstd = stddev\n\n\ndef stddev_pop(c):\n    return _agg(\"stddev_pop\", c, lambda vals: None if _var(vals, False) is None else _var(vals, False) ** 0.5)\n\n\ndef variance(c):\n    return _agg(\"variance\", c, _var)\n\n\nvar_samp = variance\n\n\ndef percentile_approx(c, percentage, accuracy=10000):\n    def f(vals):\n        v = sorted(_nn(vals))\n        if not v:\n            return None\n        def one(p):\n            k = _bmax(0, int(_math.ceil(p * len(v))) - 1)\n            return v[k]\n        return [one(p) for p in percentage] if isinstance(percentage, (list, tuple)) else one(percentage)\n    return _agg(\"percentile_approx\", c, f)\n\n\ndef median(c):\n    def f(vals):\n        v = sorted(_nn(vals))\n        if not v:\n            return None\n        n = len(v)\n        return float(v[n // 2]) if n % 2 else (v[n // 2 - 1] + v[n // 2]) / 2\n    return _agg(\"median\", c, f)\n\n\ndef corr(a, b):\n    tup = Column(\"fn\", \"pair\", [_c(a), _c(b)], lambda x, y: None if x is None or y is None else (x, y))\n\n    def f(vals):\n        v = _nn(vals)\n        n = len(v)\n        if n < 2:\n            return None\n        mx = _bsum(x for x, _ in v) / n\n        my = _bsum(y for _, y in v) / n\n        sxy = _bsum((x - mx) * (y - my) for x, y in v)\n        sx = _bsum((x - mx) ** 2 for x, _ in v) ** 0.5\n        sy = _bsum((y - my) ** 2 for _, y in v) ** 0.5\n        return sxy / (sx * sy) if sx and sy else None\n    return Column(\"agg\", \"corr(%s, %s)\" % (_c(a)._name, _c(b)._name), [tup], f)\n\n\n# ------------------------------------------------------- funciones de ventana\ndef _winfn(name, func, args=()):\n    return Column(\"win\", name, [], None, func=func, args=list(args), spec=None)\n\n\ndef row_number():\n    return _winfn(\"row_number()\", \"row_number\")\n\n\ndef rank():\n    return _winfn(\"rank()\", \"rank\")\n\n\ndef dense_rank():\n    return _winfn(\"dense_rank()\", \"dense_rank\")\n\n\ndef percent_rank():\n    return _winfn(\"percent_rank()\", \"percent_rank\")\n\n\ndef cume_dist():\n    return _winfn(\"cume_dist()\", \"cume_dist\")\n\n\ndef ntile(n):\n    return _winfn(\"ntile(%d)\" % n, \"ntile\", [n])\n\n\ndef lag(c, offset=1, default=None):\n    cc = _c(c)\n    return _winfn(\"lag(%s, %d, %s)\" % (cc._name, offset, default), \"lag\", [cc, offset, default])\n\n\ndef lead(c, offset=1, default=None):\n    cc = _c(c)\n    return _winfn(\"lead(%s, %d, %s)\" % (cc._name, offset, default), \"lead\", [cc, offset, default])\n\n\ndef nth_value(c, n):\n    raise NotImplementedError(\"nth_value no está disponible en el simulador\")\n\n\n# -------------------------------------------------------- condicionales y nulos\ndef when(cond, value):\n    return Column(\"when\", \"CASE WHEN %s THEN %s END\" % (cond._name, _as_col(value)._name), [], None, branches=[(cond, value)])\n\n\ndef coalesce(*cols):\n    def f(*a):\n        for x in a:\n            if x is not None:\n                return x\n        return None\n    return _fn(\"coalesce\", cols, f)\n\n\ndef isnull(c):\n    return _c(c).isNull()\n\n\ndef isnan(c):\n    return _fn(\"isnan\", [c], lambda x: isinstance(x, float) and x != x)\n\n\ndef nanvl(a, b):\n    return _fn(\"nanvl\", [a, b], lambda x, y: y if isinstance(x, float) and x != x else x)\n\n\ndef greatest(*cols):\n    return _fn(\"greatest\", cols, lambda *a: _bmax(_nn(a)) if _nn(a) else None)\n\n\ndef least(*cols):\n    return _fn(\"least\", cols, lambda *a: _bmin(_nn(a)) if _nn(a) else None)\n\n\ndef ifnull(a, b):\n    return coalesce(a, b)\n\n\nnvl = ifnull\n\n\ndef nullif(a, b):\n    return _fn(\"nullif\", [a, b], lambda x, y: None if x == y else x)\n\n\n# ----------------------------------------------------------- matemáticas\ndef _round_half_up(x, d=0):\n    if x is None:\n        return None\n    if isinstance(x, int) and d >= 0:\n        return x\n    m = 10 ** d\n    v = _math.floor(_babs(x) * m + 0.5 + 1e-9) / m\n    v = -v if x < 0 else v\n    return v if d > 0 else float(v)\n\n\ndef round(c, scale=0):\n    return _fn(\"round\", [c], lambda x: _round_half_up(x, scale))\n\n\ndef bround(c, scale=0):\n    return _fn(\"bround\", [c], _null_safe(lambda x: _bround(x, scale)))\n\n\ndef abs(c):\n    return _fn(\"abs\", [c], _null_safe(_babs))\n\n\ndef sqrt(c):\n    return _fn(\"SQRT\", [c], _null_safe(lambda x: _math.sqrt(x) if x >= 0 else None))\n\n\ndef pow(a, b):\n    return _fn(\"POWER\", [a, b], _null_safe(lambda x, y: float(x) ** y))\n\n\npower = pow\n\n\ndef exp(c):\n    return _fn(\"EXP\", [c], _null_safe(_math.exp))\n\n\ndef log(arg1, arg2=None):\n    if arg2 is None:\n        return _fn(\"ln\", [arg1], _null_safe(lambda x: _math.log(x) if x > 0 else None))\n    return _fn(\"LOG\", [arg2], _null_safe(lambda x: _math.log(x, arg1) if x > 0 else None))\n\n\ndef log10(c):\n    return _fn(\"LOG10\", [c], _null_safe(lambda x: _math.log10(x) if x > 0 else None))\n\n\ndef floor(c):\n    return _fn(\"FLOOR\", [c], _null_safe(lambda x: int(_math.floor(x))))\n\n\ndef ceil(c):\n    return _fn(\"CEIL\", [c], _null_safe(lambda x: int(_math.ceil(x))))\n\n\ndef signum(c):\n    return _fn(\"SIGNUM\", [c], _null_safe(lambda x: float((x > 0) - (x < 0))))\n\n\ndef rand(seed=None):\n    import random\n    r = random.Random(seed)\n    return Column(\"fn\", \"rand()\", [], lambda: r.random())\n\n\ndef monotonically_increasing_id():\n    def run(df, children):\n        return list(range(len(df._rows)))\n    return Column(\"fn\", \"monotonically_increasing_id()\", [], run, rowwise_df=True)\n\n\n# ----------------------------------------------------------------- strings\ndef upper(c):\n    return _fn(\"upper\", [c], _null_safe(lambda s: str(s).upper()))\n\n\ndef lower(c):\n    return _fn(\"lower\", [c], _null_safe(lambda s: str(s).lower()))\n\n\ndef initcap(c):\n    return _fn(\"initcap\", [c], _null_safe(lambda s: \" \".join(w[:1].upper() + w[1:].lower() for w in str(s).split(\" \"))))\n\n\ndef trim(c):\n    return _fn(\"trim\", [c], _null_safe(lambda s: str(s).strip(\" \")))\n\n\ndef ltrim(c):\n    return _fn(\"ltrim\", [c], _null_safe(lambda s: str(s).lstrip(\" \")))\n\n\ndef rtrim(c):\n    return _fn(\"rtrim\", [c], _null_safe(lambda s: str(s).rstrip(\" \")))\n\n\ndef length(c):\n    return _fn(\"length\", [c], _null_safe(lambda s: len(str(s))))\n\n\ndef concat(*cols):\n    def f(*a):\n        if any(x is None for x in a):\n            return None\n        if a and all(isinstance(x, list) for x in a):\n            return [y for x in a for y in x]\n        return \"\".join(_s(x) for x in a)\n    return _fn(\"concat\", cols, f)\n\n\ndef _s(x):\n    if isinstance(x, bool):\n        return \"true\" if x else \"false\"\n    return str(x)\n\n\ndef concat_ws(sep, *cols):\n    def f(*a):\n        parts = []\n        for x in a:\n            if x is None:\n                continue\n            if isinstance(x, list):\n                parts.extend(_s(y) for y in x if y is not None)\n            else:\n                parts.append(_s(x))\n        return sep.join(parts)\n    return _fn(\"concat_ws\", cols, f)\n\n\ndef substring(c, pos, length):\n    def f(s):\n        s = str(s)\n        start = pos - 1 if pos > 0 else len(s) + pos\n        return s[_bmax(start, 0):_bmax(start, 0) + length]\n    return _fn(\"substring\", [c], _null_safe(f))\n\n\ndef substring_index(c, delim, count):\n    def f(s):\n        parts = str(s).split(delim)\n        return delim.join(parts[:count]) if count > 0 else delim.join(parts[count:])\n    return _fn(\"substring_index\", [c], _null_safe(f))\n\n\ndef split(c, pattern, limit=-1):\n    return _fn(\"split\", [c], _null_safe(lambda s: _re.split(pattern, str(s), maxsplit=0 if limit <= 0 else limit - 1)))\n\n\ndef regexp_replace(c, pattern, replacement):\n    rep = _re.sub(r\"\\$(\\d)\", r\"\\\\\\1\", replacement)\n    return _fn(\"regexp_replace\", [c], _null_safe(lambda s: _re.sub(pattern, rep, str(s))))\n\n\ndef regexp_extract(c, pattern, idx=1):\n    def f(s):\n        m = _re.search(pattern, str(s))\n        if not m:\n            return \"\"\n        return m.group(idx) or \"\"\n    return _fn(\"regexp_extract\", [c], _null_safe(f))\n\n\ndef lpad(c, n, pad):\n    return _fn(\"lpad\", [c], _null_safe(lambda s: (pad * n + str(s))[-n:] if len(str(s)) < n else str(s)[:n]))\n\n\ndef rpad(c, n, pad):\n    return _fn(\"rpad\", [c], _null_safe(lambda s: (str(s) + pad * n)[:n]))\n\n\ndef reverse(c):\n    return _fn(\"reverse\", [c], _null_safe(lambda s: s[::-1] if isinstance(s, list) else str(s)[::-1]))\n\n\ndef translate(c, matching, replace):\n    table = {ord(a): (replace[i] if i < len(replace) else None) for i, a in enumerate(matching)}\n    return _fn(\"translate\", [c], _null_safe(lambda s: str(s).translate(table)))\n\n\ndef instr(c, substr):\n    return _fn(\"instr\", [c], _null_safe(lambda s: str(s).find(substr) + 1))\n\n\ndef locate(substr, c, pos=1):\n    return _fn(\"locate\", [c], _null_safe(lambda s: str(s).find(substr, pos - 1) + 1))\n\n\ndef format_number(c, d):\n    return _fn(\"format_number\", [c], _null_safe(lambda x: (\"{:,.%df}\" % d).format(x)))\n\n\ndef format_string(fmt, *cols):\n    return _fn(\"format_string\", cols, lambda *a: fmt % a)\n\n\ndef md5(c):\n    import hashlib\n    return _fn(\"md5\", [c], _null_safe(lambda s: hashlib.md5(str(s).encode()).hexdigest()))\n\n\ndef sha2(c, bits=256):\n    import hashlib\n    return _fn(\"sha2\", [c], _null_safe(lambda s: hashlib.new(\"sha%d\" % bits, str(s).encode()).hexdigest()))\n\n\ndef hash(*cols):\n    import hashlib\n    return _fn(\"hash\", cols, lambda *a: int(hashlib.md5(repr(a).encode()).hexdigest()[:7], 16))\n\n\ndef xxhash64(*cols):\n    return hash(*cols)\n\n\n# ------------------------------------------------------------------- fechas\ndef current_date():\n    return Column(\"fn\", \"current_date()\", [], lambda: _dt.date.today())\n\n\ndef current_timestamp():\n    return Column(\"fn\", \"current_timestamp()\", [], lambda: _dt.datetime.now().replace(microsecond=0))\n\n\nnow = current_timestamp\n\n\ndef to_date(c, fmt=None):\n    c2 = _fn(\"to_date\", [c], lambda v: _to_date(v, fmt))\n    from . import types as T\n    c2.kw[\"dtype\"] = T.DateType()\n    return c2\n\n\ndef to_timestamp(c, fmt=None):\n    c2 = _fn(\"to_timestamp\", [c], lambda v: _to_ts(v, fmt))\n    from . import types as T\n    c2.kw[\"dtype\"] = T.TimestampType()\n    return c2\n\n\ndef _d(f):\n    def g(v):\n        d = _to_ts(v) if not isinstance(v, _dt.date) or isinstance(v, _dt.datetime) else v\n        if d is None:\n            return None\n        return f(d)\n    return g\n\n\ndef year(c): return _fn(\"year\", [c], _d(lambda d: d.year))\ndef month(c): return _fn(\"month\", [c], _d(lambda d: d.month))\ndef dayofmonth(c): return _fn(\"dayofmonth\", [c], _d(lambda d: d.day))\ndef dayofweek(c): return _fn(\"dayofweek\", [c], _d(lambda d: (d.isoweekday() % 7) + 1))\ndef dayofyear(c): return _fn(\"dayofyear\", [c], _d(lambda d: d.timetuple().tm_yday))\ndef weekofyear(c): return _fn(\"weekofyear\", [c], _d(lambda d: d.isocalendar()[1]))\ndef quarter(c): return _fn(\"quarter\", [c], _d(lambda d: (d.month - 1) // 3 + 1))\ndef hour(c): return _fn(\"hour\", [c], _d(lambda d: getattr(d, \"hour\", 0)))\ndef minute(c): return _fn(\"minute\", [c], _d(lambda d: getattr(d, \"minute\", 0)))\ndef second(c): return _fn(\"second\", [c], _d(lambda d: getattr(d, \"second\", 0)))\n\n\nday = dayofmonth\n\n\ndef date_format(c, fmt):\n    return _fn(\"date_format\", [c], lambda v: None if _to_ts(v) is None else _to_ts(v).strftime(_java_fmt(fmt)))\n\n\ndef datediff(end, start):\n    return _fn(\"datediff\", [end, start], lambda a, b: None if _to_date(a) is None or _to_date(b) is None else (_to_date(a) - _to_date(b)).days)\n\n\ndef date_add(c, days):\n    return _fn(\"date_add\", [c], lambda v: None if _to_date(v) is None else _to_date(v) + _dt.timedelta(days=days))\n\n\ndef date_sub(c, days):\n    return _fn(\"date_sub\", [c], lambda v: None if _to_date(v) is None else _to_date(v) - _dt.timedelta(days=days))\n\n\ndef add_months(c, n):\n    def f(v):\n        d = _to_date(v)\n        if d is None:\n            return None\n        m = d.month - 1 + n\n        y = d.year + m // 12\n        m = m % 12 + 1\n        import calendar\n        return _dt.date(y, m, _bmin(d.day, calendar.monthrange(y, m)[1]))\n    return _fn(\"add_months\", [c], f)\n\n\ndef months_between(end, start, roundOff=True):\n    def f(a, b):\n        a, b = _to_date(a), _to_date(b)\n        if a is None or b is None:\n            return None\n        r = (a.year - b.year) * 12 + (a.month - b.month) + (a.day - b.day) / 31\n        return _bround(r, 8) if roundOff else r\n    return _fn(\"months_between\", [end, start], f)\n\n\ndef last_day(c):\n    return _fn(\"last_day\", [c], lambda v: None if _to_date(v) is None else _last_day(_to_date(v)))\n\n\ndef trunc(c, fmt):\n    return _fn(\"trunc\", [c], lambda v: None if v is None else _to_date(_trunc(v, fmt, as_date=True)))\n\n\ndef date_trunc(fmt, c):\n    return _fn(\"date_trunc\", [c], lambda v: None if v is None else _to_ts(_trunc(v, fmt)))\n\n\ndef unix_timestamp(c=None, fmt=None):\n    if c is None:\n        return Column(\"fn\", \"unix_timestamp()\", [], lambda: int(_dt.datetime.now().timestamp()))\n    return _fn(\"unix_timestamp\", [c], lambda v: None if _to_ts(v, fmt) is None else int(_to_ts(v, fmt).replace(tzinfo=_dt.timezone.utc).timestamp()))\n\n\ndef from_unixtime(c, fmt=\"yyyy-MM-dd HH:mm:ss\"):\n    return _fn(\"from_unixtime\", [c], _null_safe(lambda x: _dt.datetime.fromtimestamp(x, _dt.timezone.utc).strftime(_java_fmt(fmt))))\n\n\ndef make_date(y, m, d):\n    return _fn(\"make_date\", [y, m, d], _null_safe(lambda a, b, c: _dt.date(int(a), int(b), int(c))))\n\n\ndef sequence(start, stop, step=None):\n    def f(a, b, *s):\n        st = s[0] if s else (1 if b >= a else -1)\n        if isinstance(a, _dt.date):\n            out, cur = [], a\n            delta = _dt.timedelta(days=st if isinstance(st, int) else 1)\n            while cur <= b:\n                out.append(cur)\n                cur = cur + delta\n            return out\n        return list(range(a, b + (1 if st > 0 else -1), st))\n    cols = [start, stop] + ([step] if step is not None else [])\n    return _fn(\"sequence\", cols, _null_safe(f))\n\n\n# ------------------------------------------------------------------ arrays\ndef array(*cols):\n    if len(cols) == 1 and isinstance(cols[0], (list, tuple)):\n        cols = cols[0]\n    return _fn(\"array\", cols, lambda *a: list(a))\n\n\ndef size(c):\n    return _fn(\"size\", [c], lambda x: -1 if x is None else len(x))\n\n\ndef array_contains(c, value):\n    return _fn(\"array_contains\", [c], _null_safe(lambda a: value in a))\n\n\ndef array_distinct(c):\n    return _fn(\"array_distinct\", [c], _null_safe(lambda a: list(dict.fromkeys(a))))\n\n\ndef array_sort(c):\n    return _fn(\"array_sort\", [c], _null_safe(lambda a: sorted(a)))\n\n\nsort_array = array_sort\n\n\ndef array_join(c, delim, null_replacement=None):\n    return _fn(\"array_join\", [c], _null_safe(lambda a: delim.join(_s(x) if x is not None else (null_replacement or \"\") for x in a if x is not None or null_replacement)))\n\n\ndef element_at(c, idx):\n    def f(a):\n        if isinstance(a, dict):\n            return a.get(idx)\n        try:\n            return a[idx - 1] if idx > 0 else a[idx]\n        except IndexError:\n            return None\n    return _fn(\"element_at\", [c], _null_safe(f))\n\n\ndef explode(c):\n    cc = _c(c)\n    return Column(\"fn\", \"col\", [cc], None, explode=True)\n\n\ndef explode_outer(c):\n    cc = _c(c)\n    return Column(\"fn\", \"col\", [cc], None, explode=True, outer=True)\n\n\ndef posexplode(c):\n    raise NotImplementedError(\"posexplode no está disponible en el simulador; usa explode\")\n\n\ndef struct(*cols):\n    from . import _mkrow\n    cs = [_c(x) for x in (cols[0] if len(cols) == 1 and isinstance(cols[0], (list, tuple)) else cols)]\n    names = [x._name for x in cs]\n    return Column(\"fn\", \"struct(%s)\" % \", \".join(names), cs, lambda *a: _mkrow(names, a))\n\n\ndef create_map(*cols):\n    cs = [_c(x) for x in cols]\n\n    def f(*a):\n        return {a[i]: a[i + 1] for i in range(0, len(a), 2)}\n    return Column(\"fn\", \"map(...)\", cs, f)\n\n\ndef to_json(c):\n    import json\n    from . import _jsonable\n\n    def f(v):\n        if hasattr(v, \"asDict\"):\n            v = v.asDict()\n        return json.dumps(v, default=_jsonable, ensure_ascii=False, separators=(\",\", \":\"))\n    return _fn(\"to_json\", [c], _null_safe(f))\n\n\ndef from_json(c, schema, options=None):\n    import json\n    return _fn(\"from_json\", [c], _null_safe(lambda s: json.loads(s)))\n\n\ndef get_json_object(c, path):\n    import json\n\n    def f(s):\n        try:\n            v = json.loads(s)\n            for part in path.lstrip(\"$\").strip(\".\").split(\".\"):\n                if part:\n                    v = v[part]\n            return v if not isinstance(v, (dict, list)) else json.dumps(v)\n        except (ValueError, KeyError, TypeError):\n            return None\n    return _fn(\"get_json_object\", [c], _null_safe(f))\n\n\n# --------------------------------------------------------------------- otros\ndef asc(c):\n    return _c(c).asc()\n\n\ndef desc(c):\n    return _c(c).desc()\n\n\ndef asc_nulls_last(c): return _c(c).asc_nulls_last()\ndef desc_nulls_first(c): return _c(c).desc_nulls_first()\n\n\ndef broadcast(df):\n    return df\n\n\ndef input_file_name():\n    return lit(\"simulado://archivo\")\n\n\ndef udf(f=None, returnType=None):\n    \"\"\"Convierte una función Python en una función de columnas (UDF).\"\"\"\n    def wrap(func):\n        def make(*cols):\n            c = _fn(getattr(func, \"__name__\", \"udf\"), cols, lambda *a: _cast(func(*a), returnType) if returnType is not None else func(*a))\n            return c\n        make.func = func\n        return make\n    if callable(f):\n        return wrap(f)\n    if f is not None and returnType is None:\n        returnType = f\n    return wrap\n\n\ndef pandas_udf(*a, **k):\n    raise NotImplementedError(\"pandas_udf no está disponible en el simulador\")\n\n\ndef transform(c, f):\n    class _Lam:\n        pass\n\n    def g(arr):\n        out = []\n        for x in arr:\n            from . import DataFrame\n            tmp = DataFrame([\"x\"], [(x,)])\n            out.append(f(_col(\"x\"))._eval(tmp)[0])\n        return out\n    return _fn(\"transform\", [c], _null_safe(g))\n\n\ndef filter(c, f):\n    def g(arr):\n        from . import DataFrame\n        out = []\n        for x in arr:\n            tmp = DataFrame([\"x\"], [(x,)])\n            if f(_col(\"x\"))._eval(tmp)[0]:\n                out.append(x)\n        return out\n    return _fn(\"filter\", [c], _null_safe(g))\n\n\ndef aggregate(*a, **k):\n    raise NotImplementedError(\"aggregate no está disponible en el simulador\")\n","pyspark/sql/types.py":"\"\"\"Tipos de datos de mini-Spark (imitan pyspark.sql.types).\"\"\"\nimport re as _re\n\n\nclass DataType:\n    _name = \"data\"\n\n    def simpleString(self):\n        return self._name\n\n    def typeName(self):\n        return self._name\n\n    def __repr__(self):\n        return self.__class__.__name__ + \"()\"\n\n    def __eq__(self, other):\n        return type(self) is type(other) and self.__dict__ == other.__dict__\n\n    def __hash__(self):\n        return hash(self.simpleString())\n\n\nclass NullType(DataType): _name = \"void\"\nclass StringType(DataType): _name = \"string\"\nclass BooleanType(DataType): _name = \"boolean\"\nclass IntegerType(DataType): _name = \"int\"\nclass LongType(DataType): _name = \"bigint\"\nclass ShortType(DataType): _name = \"smallint\"\nclass ByteType(DataType): _name = \"tinyint\"\nclass FloatType(DataType): _name = \"float\"\nclass DoubleType(DataType): _name = \"double\"\nclass DateType(DataType): _name = \"date\"\nclass TimestampType(DataType): _name = \"timestamp\"\nclass BinaryType(DataType): _name = \"binary\"\n\n\nclass DecimalType(DataType):\n    def __init__(self, precision=10, scale=0):\n        self.precision = precision\n        self.scale = scale\n\n    def simpleString(self):\n        return \"decimal(%d,%d)\" % (self.precision, self.scale)\n\n    def __repr__(self):\n        return \"DecimalType(%d,%d)\" % (self.precision, self.scale)\n\n\nclass ArrayType(DataType):\n    def __init__(self, elementType, containsNull=True):\n        self.elementType = elementType\n        self.containsNull = containsNull\n\n    def simpleString(self):\n        return \"array<%s>\" % self.elementType.simpleString()\n\n    def __repr__(self):\n        return \"ArrayType(%r, %s)\" % (self.elementType, self.containsNull)\n\n\nclass MapType(DataType):\n    def __init__(self, keyType, valueType, valueContainsNull=True):\n        self.keyType = keyType\n        self.valueType = valueType\n\n    def simpleString(self):\n        return \"map<%s,%s>\" % (self.keyType.simpleString(), self.valueType.simpleString())\n\n\nclass StructField:\n    def __init__(self, name, dataType, nullable=True, metadata=None):\n        self.name = name\n        self.dataType = dataType\n        self.nullable = nullable\n\n    def simpleString(self):\n        return \"%s:%s\" % (self.name, self.dataType.simpleString())\n\n    def __repr__(self):\n        return \"StructField('%s', %r, %s)\" % (self.name, self.dataType, self.nullable)\n\n    def __eq__(self, o):\n        return isinstance(o, StructField) and (self.name, self.dataType, self.nullable) == (o.name, o.dataType, o.nullable)\n\n\nclass StructType(DataType):\n    _name = \"struct\"\n\n    def __init__(self, fields=None):\n        self.fields = list(fields or [])\n\n    def add(self, field, data_type=None, nullable=True):\n        if isinstance(field, StructField):\n            self.fields.append(field)\n        else:\n            if isinstance(data_type, str):\n                data_type = _parse_type(data_type)\n            self.fields.append(StructField(field, data_type, nullable))\n        return self\n\n    @property\n    def names(self):\n        return [f.name for f in self.fields]\n\n    def fieldNames(self):\n        return self.names\n\n    def __iter__(self):\n        return iter(self.fields)\n\n    def __len__(self):\n        return len(self.fields)\n\n    def __getitem__(self, k):\n        if isinstance(k, str):\n            for f in self.fields:\n                if f.name == k:\n                    return f\n            raise KeyError(k)\n        return self.fields[k]\n\n    def simpleString(self):\n        return \"struct<%s>\" % \",\".join(f.simpleString() for f in self.fields)\n\n    def __repr__(self):\n        return \"StructType([%s])\" % \", \".join(repr(f) for f in self.fields)\n\n    def treeString(self):\n        lines = [\"root\"]\n        for f in self.fields:\n            lines.append(\" |-- %s: %s (nullable = %s)\" % (f.name, f.dataType.simpleString(), str(f.nullable).lower()))\n        return \"\\n\".join(lines)\n\n\n_SIMPLE = {\n    \"string\": StringType, \"str\": StringType, \"varchar\": StringType, \"char\": StringType,\n    \"int\": IntegerType, \"integer\": IntegerType, \"bigint\": LongType, \"long\": LongType,\n    \"smallint\": ShortType, \"short\": ShortType, \"tinyint\": ByteType, \"byte\": ByteType,\n    \"double\": DoubleType, \"float\": FloatType, \"real\": FloatType,\n    \"boolean\": BooleanType, \"bool\": BooleanType, \"date\": DateType, \"timestamp\": TimestampType,\n    \"binary\": BinaryType,\n}\n\n\ndef _parse_type(s):\n    if isinstance(s, DataType):\n        return s\n    t = s.strip().lower()\n    m = _re.match(r\"^(decimal|numeric)\\s*\\(\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\)$\", t)\n    if m:\n        return DecimalType(int(m.group(2)), int(m.group(3)))\n    if t in (\"decimal\", \"numeric\"):\n        return DecimalType(10, 0)\n    m = _re.match(r\"^array\\s*<(.+)>$\", t)\n    if m:\n        return ArrayType(_parse_type(m.group(1)))\n    t = _re.sub(r\"\\(.*\\)$\", \"\", t)\n    if t in _SIMPLE:\n        return _SIMPLE[t]()\n    raise ValueError(\"Tipo desconocido: %s\" % s)\n\n\ndef _parse_schema(s):\n    \"\"\"'nombre STRING, edad INT' o 'nombre: string, edad: int' -> StructType\"\"\"\n    fields = []\n    depth, cur, parts = 0, \"\", []\n    for ch in s:\n        if ch in \"<(\":\n            depth += 1\n        elif ch in \">)\":\n            depth -= 1\n        if ch == \",\" and depth == 0:\n            parts.append(cur)\n            cur = \"\"\n        else:\n            cur += ch\n    if cur.strip():\n        parts.append(cur)\n    for p in parts:\n        p = p.strip()\n        if \":\" in p:\n            name, typ = p.split(\":\", 1)\n        else:\n            bits = p.split(None, 1)\n            if len(bits) != 2:\n                raise ValueError(\"No entiendo el esquema: %r\" % p)\n            name, typ = bits\n        nullable = True\n        typ = typ.strip()\n        if typ.upper().endswith(\"NOT NULL\"):\n            nullable = False\n            typ = typ[:-8]\n        fields.append(StructField(name.strip().strip(\"`\"), _parse_type(typ), nullable))\n    return StructType(fields)\n","pyspark/sql/utils.py":"from . import AnalysisException  # noqa: F401\n","pyspark/sql/window.py":"\"\"\"Especificaciones de ventana (imitan pyspark.sql.window).\"\"\"\n\n\nclass WindowSpec:\n    def __init__(self, partition=None, order=None, frame=None):\n        self._partition = list(partition or [])\n        self._order = list(order or [])\n        self._frame = frame\n\n    def partitionBy(self, *cols):\n        cols = _flat(cols)\n        return WindowSpec(self._partition + cols, self._order, self._frame)\n\n    def orderBy(self, *cols):\n        cols = _flat(cols)\n        return WindowSpec(self._partition, self._order + cols, self._frame)\n\n    def rowsBetween(self, start, end):\n        return WindowSpec(self._partition, self._order, (\"rows\", _bound(start), _bound(end)))\n\n    def rangeBetween(self, start, end):\n        return WindowSpec(self._partition, self._order, (\"range\", _bound(start), _bound(end)))\n\n\ndef _flat(cols):\n    out = []\n    for c in cols:\n        if isinstance(c, (list, tuple)):\n            out.extend(c)\n        else:\n            out.append(c)\n    from . import _col\n    return [_col(c) if isinstance(c, str) else c for c in out]\n\n\ndef _bound(x):\n    if x is None or abs(x) >= Window.unboundedFollowing:\n        return None\n    return x\n\n\nclass Window:\n    unboundedPreceding = -(1 << 62)\n    unboundedFollowing = (1 << 62)\n    currentRow = 0\n\n    @staticmethod\n    def partitionBy(*cols):\n        return WindowSpec().partitionBy(*cols)\n\n    @staticmethod\n    def orderBy(*cols):\n        return WindowSpec().orderBy(*cols)\n\n    @staticmethod\n    def rowsBetween(start, end):\n        return WindowSpec().rowsBetween(start, end)\n\n    @staticmethod\n    def rangeBetween(start, end):\n        return WindowSpec().rangeBetween(start, end)\n"};
